package com.prometheus.clq.data

import com.prometheus.clq.model.Difficulty
import com.prometheus.clq.model.Question

/**
 * Expansion 1 — ~250 questions
 * Focus: Musique, Mythologie, Nature, Politique, Littérature, Économie, Sciences Humaines, Philosophie
 */
object QuestionsExpansion1 {
    fun get(): List<Question> = musique() + mythologie() + nature() + politique() + litterature() + economie() + sciencesHumaines() + philosophie()

    // ===== MUSIQUE — 50 questions =====
    private fun musique(): List<Question> = listOf(
        Question(20001, "Quel groupe a chanté 'Bohemian Rhapsody' ?", listOf("Queen", "The Beatles", "Led Zeppelin", "Pink Floyd"), 0, "Musique", Difficulty.EASY, explanation = "Queen a sorti Bohemian Rhapsody en 1975 sur l'album A Night at the Opera. La chanson est devenue un immense succès mondial et un classique du rock."),
        Question(20002, "Combien de touches possède un piano standard ?", listOf("88", "76", "92", "84"), 0, "Musique", Difficulty.MEDIUM, explanation = "Le piano standard compte 88 touches, soit 52 blanches et 36 noires, une norme établie depuis la fin du XIXe siècle pour couvrir toute la tessiture musicale."),
        Question(20003, "Quel instrument de musique a 47 cordes ?", listOf("La harpe", "Le clavecin", "La guitare classique", "Le luth"), 0, "Musique", Difficulty.HARD, explanation = "La harpe de concert standard possède 47 cordes, ce qui lui permet de couvrir une large gamme de notes allant du do grave au sol aigu."),
        Question(20005, "Quel est le tempo standard d'un Andante ?", listOf("76-108 BPM", "120-156 BPM", "40-60 BPM", "160-200 BPM"), 0, "Musique", Difficulty.HARD, explanation = "L'andante est un tempo modéré, souvent décrit comme un rythme de marche, et sa plage standard de 76 à 108 battements par minute est définie par la notation musicale classique."),
        Question(20006, "Quel chanteur français est surnommé 'L'Aznavour de la chanson' ?", listOf("Charles Aznavour", "Jacques Brel", "Serge Gainsbourg", "Claude François"), 0, "Musique", Difficulty.EASY, explanation = "Charles Aznavour est lui-même le chanteur français désigné par ce surnom, car il est une icône de la chanson française."),
        Question(20008, "Quel genre musical est né à la Nouvelle-Orléans ?", listOf("Le jazz", "Le blues", "Le rock", "Le country"), 0, "Musique", Difficulty.EASY, explanation = "La Nouvelle-Orléans est considérée comme le berceau du jazz, né au début du XXe siècle du mélange des musiques africaines, européennes et du blues."),
        Question(20009, "Quel rappeur français a sorti l'album 'Civilisation' ?", listOf("Orelsan", "Nekfeu", "Booba", "PNL"), 0, "Musique", Difficulty.MEDIUM, explanation = "Orelsan a sorti l'album \"Civilisation\" en 2021, après une longue absence. Ce disque a remporté plusieurs Victoires de la musique."),
        Question(20010, "Quel compositeur a écrit 'Le Lac des cygnes' ?", listOf("Tchaïkovski", "Stravinsky", "Prokofiev", "Rimski-Korsakov"), 0, "Musique", Difficulty.MEDIUM, explanation = "Tchaïkovski a composé Le Lac des cygnes en 1875-1876 pour le ballet du Théâtre Bolchoï à Moscou. C'est l'un des ballets les plus célèbres de l'histoire de la musique classique."),
        Question(20011, "Quelle note de musique correspond au 'La' de référence ?", listOf("440 Hz", "520 Hz", "380 Hz", "460 Hz"), 0, "Musique", Difficulty.HARD, explanation = "Le La de référence est fixé à 440 Hz depuis une conférence internationale en 1939, standard adopté pour accorder les instruments de musique."),
        Question(20012, "Quel groupe a vendu le plus d'albums dans l'histoire ?", listOf("The Beatles", "Led Zeppelin", "Pink Floyd", "Eagles"), 0, "Musique", Difficulty.MEDIUM, explanation = "Les Beatles ont vendu plus de 600 millions d'albums dans le monde, un record inégalé grâce à leur popularité massive dans les années 1960 et leur influence durable."),
        Question(20013, "Quel instrument est surnommé le 'roi des instruments' ?", listOf("L'orgue", "Le piano", "Le violon", "La trompette"), 0, "Musique", Difficulty.MEDIUM, explanation = "L'orgue est surnommé le « roi des instruments » en raison de sa puissance sonore, de sa complexité mécanique et de son rôle central dans la musique liturgique et classique."),
        Question(20014, "En quelle année est sorti l'album 'Thriller' de Michael Jackson ?", listOf("1982", "1984", "1980", "1986"), 0, "Musique", Difficulty.MEDIUM, explanation = "L'album 'Thriller' est sorti le 30 novembre 1982, devenant l'album le plus vendu de tous les temps avec des titres comme 'Billie Jean' et 'Beat It'."),
        Question(20015, "Quel musicien a popularisé la guitare électrique ?", listOf("Jimi Hendrix", "Eric Clapton", "Chuck Berry", "B.B. King"), 0, "Musique", Difficulty.MEDIUM, explanation = "Jimi Hendrix a révolutionné le jeu de la guitare électrique dans les années 1960 avec son style innovant et ses effets sonores, devenant une icône du rock."),
        Question(20016, "Combien de mouvements a généralement une symphonie classique ?", listOf("4", "3", "5", "2"), 0, "Musique", Difficulty.HARD, explanation = "La symphonie classique, notamment chez Haydn et Mozart, est structurée en quatre mouvements contrastants : un allegro, un adagio, un menuet ou scherzo, et un finale rapide."),
        Question(20017, "Quel DJ français a produit 'Interstella 5555' avec les Daft Punk ?", listOf("Daft Punk eux-mêmes", "David Guetta", "Martin Solveig", "Bob Sinclar"), 0, "Musique", Difficulty.MEDIUM, explanation = "Le film d'animation Interstella 5555 est une adaptation visuelle de l'album Discovery, produit et réalisé par les Daft Punk eux-mêmes, sans DJ extérieur."),
        Question(20018, "Quel est le vrai nom d'Eminem ?", listOf("Marshall Mathers", "Curtis Jackson", "Andre Young", "Shawn Carter"), 0, "Musique", Difficulty.MEDIUM, explanation = "Marshall Mathers est le nom de naissance du rappeur, qu'il utilise comme nom de scène dans son album The Marshall Mathers LP."),
        Question(20019, "Quel opéra commence par 'La donna è mobile' ?", listOf("Rigoletto", "La Traviata", "Aida", "Carmen"), 0, "Musique", Difficulty.HARD, explanation = "Cet air célèbre est chanté par le duc de Mantoue dans l'acte III de Rigoletto, opéra de Giuseppe Verdi créé en 1851."),
        Question(20020, "Quel pays a inventé le karaoké ?", listOf("Le Japon", "La Corée du Sud", "Les États-Unis", "Les Philippines"), 0, "Musique", Difficulty.MEDIUM, explanation = "Le karaoké a été inventé par le musicien japonais Daisuke Inoue en 1971 à Kobe, au Japon."),
        Question(20021, "Quelle chanteuse est surnommée 'Queen B' ?", listOf("Beyoncé", "Britney Spears", "Billie Eilish", "Barbara Streisand"), 0, "Musique", Difficulty.EASY, explanation = "Beyoncé est souvent appelée Queen B par ses fans et les médias, un surnom qui reflète son statut d'icône mondiale de la musique pop et R&B."),
        Question(20022, "Quel instrument est à la base du reggae ?", listOf("La guitare basse", "La batterie", "Le piano", "Le saxophone"), 0, "Musique", Difficulty.MEDIUM, explanation = "La guitare basse est l'instrument fondamental du reggae car elle assure la ligne rythmique et mélodique principale, souvent en contrepoint avec la batterie, créant le groove caractéristique du genre."),
        Question(20023, "De quel pays vient le fado ?", listOf("Le Portugal", "L'Espagne", "Le Brésil", "L'Italie"), 0, "Musique", Difficulty.MEDIUM, explanation = "Le fado est un genre musical traditionnel portugais, reconnu comme patrimoine culturel immatériel de l'humanité par l'UNESCO."),
        Question(20025, "Quel artiste a chanté 'Imagine' ?", listOf("John Lennon", "Paul McCartney", "Bob Dylan", "Elton John"), 0, "Musique", Difficulty.EASY, explanation = "John Lennon a écrit et interprété 'Imagine' en 1971, une chanson devenue un hymne mondial pour la paix."),
        Question(20026, "Comment s'appelle la technique de chant sans paroles utilisée en jazz ?", listOf("Le scat", "Le beatbox", "Le yodel", "Le falsetto"), 0, "Musique", Difficulty.HARD, explanation = "Le scat est une technique vocale jazz où le chanteur improvise des syllabes et des sons sans signification, popularisée par des artistes comme Louis Armstrong."),
        Question(20027, "Quel est le plus ancien instrument de musique connu ?", listOf("La flûte en os", "Le tambour", "La lyre", "La corne"), 0, "Musique", Difficulty.HARD, explanation = "La flûte en os, découverte dans des grottes en Allemagne, date d'environ 40 000 ans et a été fabriquée par l'homme de Néandertal."),
        Question(20028, "Quel compositeur russe a écrit 'L'Oiseau de feu' ?", listOf("Igor Stravinsky", "Sergueï Rachmaninov", "Dmitri Chostakovitch", "Sergueï Prokofiev"), 0, "Musique", Difficulty.HARD, explanation = "Igor Stravinsky a composé L'Oiseau de feu en 1910 pour les Ballets russes de Diaghilev, ce qui l'a rendu célèbre du jour au lendemain."),
        Question(20029, "Quel festival de musique se tient à Glastonbury ?", listOf("Un festival de rock et pop", "Un festival de jazz", "Un festival de classique", "Un festival d'opéra"), 0, "Musique", Difficulty.EASY, explanation = "Le festival de Glastonbury, créé en 1970, est principalement dédié au rock et à la pop, bien qu'il inclue aussi d'autres genres musicaux."),
        Question(20030, "Quelle est la tessiture vocale la plus grave chez l'homme ?", listOf("Basse", "Baryton", "Ténor", "Contre-ténor"), 0, "Musique", Difficulty.MEDIUM, explanation = "La basse est la voix masculine la plus grave, située en dessous du baryton et du ténor."),
        Question(20031, "Quel groupe a chanté 'Stairway to Heaven' ?", listOf("Led Zeppelin", "Pink Floyd", "Deep Purple", "Black Sabbath"), 0, "Musique", Difficulty.EASY, explanation = "Led Zeppelin a sorti ce morceau emblématique en 1971 sur l'album Led Zeppelin IV, devenu l'un des titres les plus célèbres du rock."),
        Question(20032, "Quelle est la gamme pentatonique ?", listOf("Une gamme à 5 notes", "Une gamme à 7 notes", "Une gamme à 12 notes", "Une gamme à 3 notes"), 0, "Musique", Difficulty.MEDIUM, explanation = "Le terme \"pentatonique\" vient du grec \"penta\" (cinq) et \"tonos\" (ton), désignant une gamme musicale composée de cinq notes par octave, contrairement aux gammes heptatoniques classiques à sept notes."),
        Question(20033, "Quel chanteur français est l'interprète de 'Ne me quitte pas' ?", listOf("Jacques Brel", "Édith Piaf", "Georges Brassens", "Léo Ferré"), 0, "Musique", Difficulty.EASY, explanation = "Jacques Brel a écrit et interprété 'Ne me quitte pas' en 1959, une chanson devenue un classique de la chanson francophone."),
        Question(20034, "Quel est le nom de la famille d'instruments à laquelle appartient le tuba ?", listOf("Les cuivres", "Les bois", "Les cordes", "Les percussions"), 0, "Musique", Difficulty.EASY, explanation = "Le tuba est un instrument à vent en métal dont le son est produit par la vibration des lèvres dans une embouchure, ce qui le classe dans la famille des cuivres."),
        Question(20035, "Quel DJ suédois, décédé en 2018, était connu pour 'Levels' ?", listOf("Avicii", "Swedish House Mafia", "Alesso", "Zedd"), 0, "Musique", Difficulty.MEDIUM, explanation = "Avicii, de son vrai nom Tim Bergling, a popularisé la musique électronique avec son tube 'Levels' en 2011, avant de se suicider en 2018 à 28 ans."),
        Question(20036, "Quelle est la clé la plus utilisée en musique classique ?", listOf("Clé de sol", "Clé de fa", "Clé d'ut", "Clé de ré"), 0, "Musique", Difficulty.MEDIUM, explanation = "La clé de sol est la plus courante car elle permet de noter les notes aiguës, utilisées par la majorité des instruments (violon, flûte, main droite du piano) et des voix féminines."),
        Question(20037, "Quel rappeur américain a sorti 'The Slim Shady LP' ?", listOf("Eminem", "Jay-Z", "Nas", "50 Cent"), 0, "Musique", Difficulty.EASY, explanation = "Eminem a sorti 'The Slim Shady LP' en 1999, son premier album sur un label majeur, qui a lancé sa carrière avec le personnage provocateur de Slim Shady."),
        Question(20038, "Quel instrument africain est un piano à pouces ?", listOf("Le kalimba (mbira)", "Le djembé", "Le balafon", "La kora"), 0, "Musique", Difficulty.HARD, explanation = "Le kalimba, aussi appelé mbira, est un instrument à lamelles pincées avec les pouces, originaire d'Afrique subsaharienne, où il est utilisé dans les traditions musicales et spirituelles."),
        Question(20039, "Quel compositeur a écrit l'Hymne à la Joie ?", listOf("Beethoven", "Mozart", "Haydn", "Schubert"), 0, "Musique", Difficulty.EASY, explanation = "L'Hymne à la Joie est le dernier mouvement de la Neuvième Symphonie de Beethoven, composée en 1824, et est devenu l'hymne officiel de l'Union européenne."),
        Question(20040, "Quelle chanteuse a interprété 'La Vie en rose' ?", listOf("Édith Piaf", "Dalida", "Mireille Mathieu", "Barbara"), 0, "Musique", Difficulty.EASY, explanation = "Édith Piaf a popularisé cette chanson en 1946, dont elle a écrit les paroles. C'est devenu l'un de ses titres emblématiques et un standard de la chanson française."),
        Question(20041, "Quel genre musical est caractérisé par le 'drop' ?", listOf("L'EDM (musique électronique)", "Le jazz", "Le blues", "Le classique"), 0, "Musique", Difficulty.EASY, explanation = "Dans l'EDM, le 'drop' désigne le moment où le rythme et la mélodie atteignent leur intensité maximale après une montée progressive, un élément clé du genre."),
        Question(20042, "Quel artiste a peint en écoutant du jazz, donnant naissance au terme 'jazz painting' ?", listOf("Piet Mondrian", "Pablo Picasso", "Henri Matisse", "Jackson Pollock"), 0, "Musique", Difficulty.EXPERT, explanation = "Piet Mondrian, fasciné par le jazz et le boogie-woogie, a créé des toiles comme Broadway Boogie-Woogie, où les rythmes syncopés ont inspiré ses compositions géométriques, popularisant ainsi le terme jazz painting."),
        Question(20043, "Combien de dièses a la tonalité de Sol majeur ?", listOf("1", "2", "3", "0"), 0, "Musique", Difficulty.HARD, explanation = "La tonalité de Sol majeur comporte un dièse, le fa dièse, car elle suit le cycle des quintes où le sol est la quinte de do majeur."),
        Question(20044, "Quel groupe de K-pop a battu des records sur YouTube ?", listOf("BTS", "BLACKPINK", "EXO", "TWICE"), 0, "Musique", Difficulty.EASY, explanation = "BTS détient plusieurs records sur YouTube, notamment celui de la vidéo la plus visionnée en 24 heures avec \"Butter\"."),
        Question(20045, "Quel est le tempo d'un Allegro ?", listOf("120-156 BPM", "60-80 BPM", "40-60 BPM", "80-108 BPM"), 0, "Musique", Difficulty.HARD, explanation = "Allegro est un terme musical italien indiquant un tempo rapide et vif, généralement situé entre 120 et 156 battements par minute (BPM)."),
        Question(20046, "Quel instrument utilise un anche double ?", listOf("Le hautbois", "La clarinette", "La flûte traversière", "Le saxophone"), 0, "Musique", Difficulty.HARD, explanation = "Le hautbois utilise une anche double, composée de deux lamelles de roseau qui vibrent l'une contre l'autre, contrairement aux anches simples comme celle de la clarinette."),
        Question(20047, "Quel chanteur a popularisé le reggaeton ?", listOf("Daddy Yankee", "Bad Bunny", "J Balvin", "Maluma"), 0, "Musique", Difficulty.MEDIUM, explanation = "Daddy Yankee est largement considéré comme le pionnier du reggaeton moderne, notamment grâce à son tube international \"Gasolina\" en 2004."),
        Question(20048, "Quelle est la durée d'une ronde en musique ?", listOf("4 temps", "2 temps", "1 temps", "8 temps"), 0, "Musique", Difficulty.MEDIUM, explanation = "La ronde est la figure de note la plus longue utilisée dans la musique mesurée, et sa durée standard est de quatre temps dans une mesure à 4/4."),
        Question(20049, "Quel musicien aveugle a révolutionné le R&B ?", listOf("Stevie Wonder", "Ray Charles", "Andrea Bocelli", "José Feliciano"), 0, "Musique", Difficulty.MEDIUM, explanation = "Stevie Wonder, aveugle de naissance, a transformé le R&B dans les années 1970 en fusionnant funk, soul et synthétiseurs, avec des albums majeurs comme Innervisions et Songs in the Key of Life."),
        Question(20050, "Quel compositeur minimaliste a écrit 'Music for 18 Musicians' ?", listOf("Steve Reich", "Philip Glass", "Terry Riley", "John Adams"), 0, "Musique", Difficulty.EXPERT, explanation = "Steve Reich, figure majeure du minimalisme américain, a composé cette œuvre emblématique en 1976, marquée par des motifs répétitifs et des déphasages rythmiques.")
    )

    // ===== MYTHOLOGIE — 50 questions =====
    private fun mythologie(): List<Question> = listOf(
        Question(20101, "Qui est le roi des dieux dans la mythologie grecque ?", listOf("Zeus", "Poséidon", "Hadès", "Arès"), 0, "Mythologie", Difficulty.EASY, explanation = "Zeus est le souverain de l'Olympe et le dieu du ciel et de la foudre dans la mythologie grecque, ayant renversé son père Cronos pour devenir le roi des dieux."),
        Question(20102, "Quel héros grec a tué la Méduse ?", listOf("Persée", "Héraclès", "Thésée", "Achille"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Persée a décapité Méduse, la seule Gorgone mortelle, avec l'aide d'objets magiques offerts par les dieux, notamment un bouclier poli pour éviter son regard pétrifiant."),
        Question(20103, "Comment s'appelle le fleuve des Enfers grecs ?", listOf("Le Styx", "Le Léthé", "L'Achéron", "Le Phlégéthon"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Le Styx est le principal fleuve des Enfers dans la mythologie grecque, souvent décrit comme une barrière entre le monde des vivants et celui des morts."),
        Question(20104, "Qui est le dieu nordique du tonnerre ?", listOf("Thor", "Odin", "Loki", "Freyr"), 0, "Mythologie", Difficulty.EASY, explanation = "Thor est le dieu du tonnerre dans la mythologie nordique, armé de son marteau Mjöllnir. Il est le fils d'Odin et protège les humains et les dieux contre les géants."),
        Question(20105, "Combien de travaux Héraclès a-t-il dû accomplir ?", listOf("12", "10", "7", "15"), 0, "Mythologie", Difficulty.EASY, explanation = "Héraclès a dû accomplir douze travaux pour expier le meurtre de ses enfants, ordonnés par l'oracle de Delphes. Ces épreuves incluent des exploits comme tuer le lion de Némée ou nettoyer les écuries d'Augias."),
        Question(20106, "Quel monstre gardait le labyrinthe de Crète ?", listOf("Le Minotaure", "Le Sphinx", "L'Hydre", "Cerbère"), 0, "Mythologie", Difficulty.EASY, explanation = "Le Minotaure, créature mi-homme mi-taureau, était enfermé dans le labyrinthe construit par Dédale pour le roi Minos, et se nourrissait de jeunes Athéniens."),
        Question(20107, "Qui est le passeur des morts dans la mythologie grecque ?", listOf("Charon", "Hermès", "Hadès", "Thanatos"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Charon est le nocher des Enfers chargé de faire traverser le Styx aux âmes des défunts, en échange d'une obole placée dans leur bouche."),
        Question(20108, "Quel arbre sacré est associé à Odin ?", listOf("Yggdrasil (le frêne)", "Le chêne", "Le bouleau", "L'if"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Yggdrasil est l'arbre-monde de la mythologie nordique, un frêne géant dont les branches relient les neuf mondes et sous lequel Odin se pendit pour acquérir la sagesse des runes."),
        Question(20109, "Qui a ouvert la boîte qui a libéré tous les maux ?", listOf("Pandore", "Hélène", "Médée", "Circé"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, Pandore, la première femme créée par les dieux, ouvrit une jarre (souvent appelée boîte) qui libéra tous les maux sur l'humanité, ne laissant que l'espoir à l'intérieur."),
        Question(20110, "Quel dieu égyptien a une tête de chacal ?", listOf("Anubis", "Horus", "Seth", "Thot"), 0, "Mythologie", Difficulty.EASY, explanation = "Anubis est le dieu égyptien de la momification et de l'au-delà, représenté avec une tête de chacal en raison de l'association de cet animal avec les nécropoles."),
        Question(20111, "Dans la mythologie nordique, qu'est-ce que le Ragnarök ?", listOf("La fin du monde", "Le paradis des guerriers", "La création de l'univers", "Le banquet des dieux"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie nordique, le Ragnarök est une série d'événements prophétiques incluant une grande bataille, la mort de nombreux dieux, et la destruction du monde par le feu et l'eau, avant sa renaissance."),
        Question(20112, "Quel héros troyen portait Anchise sur son dos ?", listOf("Énée", "Hector", "Pâris", "Priam"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque et romaine, Énée a sauvé son père Anchise de la ville en flammes de Troie en le portant sur ses épaules."),
        Question(20113, "Qui est la déesse grecque de la sagesse ?", listOf("Athéna", "Artémis", "Aphrodite", "Héra"), 0, "Mythologie", Difficulty.EASY, explanation = "Athéna, fille de Zeus, est née armée de son crâne et incarne la sagesse, la stratégie militaire et les arts. Elle est la déesse protectrice d'Athènes."),
        Question(20114, "Quel titan portait le monde sur ses épaules ?", listOf("Atlas", "Cronos", "Prométhée", "Hypérion"), 0, "Mythologie", Difficulty.EASY, explanation = "Atlas, condamné par Zeus à soutenir la voûte céleste, est souvent représenté portant le globe terrestre sur ses épaules."),
        Question(20115, "Comment s'appelle le loup géant de la mythologie nordique ?", listOf("Fenrir", "Sköll", "Hati", "Garm"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Fenrir est le loup monstrueux, fils de Loki, dont la prophétie annonce qu'il dévorera Odin lors du Ragnarök."),
        Question(20116, "Quel dieu hindou a une tête d'éléphant ?", listOf("Ganesh", "Vishnou", "Shiva", "Brahma"), 0, "Mythologie", Difficulty.EASY, explanation = "Ganesh est le dieu hindou de la sagesse et de l'abondance, reconnaissable à sa tête d'éléphant, symbole de sa naissance légendaire après que Shiva lui a tranché la tête et l'a remplacée par celle d'un éléphant."),
        Question(20117, "Qui a volé le feu pour le donner aux humains ?", listOf("Prométhée", "Épiméthée", "Hermès", "Héphaïstos"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, Prométhée, un Titan, déroba le feu sacré de l'Olympe pour l'offrir aux mortels, défiant ainsi la volonté de Zeus."),
        Question(20118, "Quel est le nom du marteau de Thor ?", listOf("Mjöllnir", "Gungnir", "Gram", "Tyrfing"), 0, "Mythologie", Difficulty.EASY, explanation = "Mjöllnir est le marteau légendaire du dieu nordique Thor, forgé par les nains Brokk et Eitri, et capable de lancer des éclairs et de revenir dans sa main."),
        Question(20119, "Combien de têtes avait l'Hydre de Lerne ?", listOf("9 (qui repoussaient)", "7", "5", "12"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "L'Hydre de Lerne, créature de la mythologie grecque, possédait neuf têtes, dont une immortelle, et chaque tête coupée repoussait."),
        Question(20120, "Quel dieu grec est le messager des dieux ?", listOf("Hermès", "Apollon", "Arès", "Dionysos"), 0, "Mythologie", Difficulty.EASY, explanation = "Hermès est le messager des dieux dans la mythologie grecque, connu pour sa rapidité et son rôle de guide des âmes vers les enfers."),
        Question(20121, "Dans la mythologie japonaise, quelle déesse du soleil se cache dans une grotte ?", listOf("Amaterasu", "Tsukuyomi", "Susanoo", "Izanami"), 0, "Mythologie", Difficulty.HARD, explanation = "Amaterasu, déesse shinto du soleil, se cacha dans la grotte d'Ama-no-Iwato après une dispute avec son frère Susanoo, plongeant le monde dans l'obscurité."),
        Question(20122, "Quel monstre grec avait un corps de lion et un visage de femme ?", listOf("Le Sphinx", "La Chimère", "Le Minotaure", "L'Hydre"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Le Sphinx, figure de la mythologie grecque, terrorisait Thèbes en posant une énigme aux voyageurs et dévorait ceux qui ne trouvaient pas la réponse."),
        Question(20123, "Qui est le dieu grec de la mer ?", listOf("Poséidon", "Zeus", "Arès", "Apollon"), 0, "Mythologie", Difficulty.EASY, explanation = "Poséidon est le dieu grec de la mer, des tremblements de terre et des chevaux, frère de Zeus et d’Hadès. Il est souvent représenté avec un trident, symbole de sa puissance sur les océans."),
        Question(20124, "Quel héros a navigué pour chercher la Toison d'or ?", listOf("Jason", "Ulysse", "Thésée", "Persée"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Jason est le héros de la mythologie grecque qui, avec les Argonautes, a entrepris la quête de la Toison d'or pour reconquérir le trône d'Iolcos."),
        Question(20125, "Quel animal était sacré pour les Égyptiens ?", listOf("Le chat", "Le chien", "Le cheval", "L'aigle"), 0, "Mythologie", Difficulty.EASY, explanation = "Les Égyptiens vénéraient les chats comme des incarnations de la déesse Bastet, protectrice du foyer et de la fertilité. Tuer un chat était un crime passible de la peine de mort."),
        Question(20126, "Comment se nomme le paradis des guerriers dans la mythologie nordique ?", listOf("Le Valhalla", "L'Asgard", "Le Niflheim", "Le Midgard"), 0, "Mythologie", Difficulty.EASY, explanation = "Le Valhalla est le grand hall d'Odin où les guerriers morts au combat, les Einherjar, festoient et s'entraînent en attendant le Ragnarök."),
        Question(20127, "Quel dieu romain correspond à Arès ?", listOf("Mars", "Mercure", "Jupiter", "Neptune"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Mars est l'équivalent romain d'Arès, le dieu grec de la guerre, dans le cadre de l'assimilation des panthéons grec et romain."),
        Question(20128, "Quelle créature mythique renaît de ses cendres ?", listOf("Le phénix", "Le dragon", "Le griffon", "La licorne"), 0, "Mythologie", Difficulty.EASY, explanation = "Le phénix est un oiseau légendaire de la mythologie grecque et égyptienne, célèbre pour son cycle de renaissance où il renaît de ses propres cendres après s'être consumé par le feu."),
        Question(20129, "Qui a coupé le nœud gordien ?", listOf("Alexandre le Grand", "Ulysse", "Achille", "Héraclès"), 0, "Mythologie", Difficulty.HARD, explanation = "Selon la légende, quiconque dénouait le nœud gordien deviendrait maître de l'Asie. Alexandre le Grand le trancha d'un coup d'épée, réalisant ainsi la prophétie."),
        Question(20130, "Quelle déesse aztèque représente la lune ?", listOf("Coyolxauhqui", "Coatlicue", "Tlazolteotl", "Xochiquetzal"), 0, "Mythologie", Difficulty.EXPERT, explanation = "Coyolxauhqui est la déesse aztèque de la lune, dont le nom signifie \"celle qui se pare de cloches\". Elle est célèbre pour avoir été démembrée par son frère Huitzilopochtli, le dieu du soleil."),
        Question(20131, "Quel est le nom du serpent mondial dans la mythologie nordique ?", listOf("Jörmungandr", "Níðhöggr", "Fáfnir", "Apep"), 0, "Mythologie", Difficulty.HARD, explanation = "Jörmungandr est le serpent géant qui entoure Midgard, le monde des humains, en se mordant la queue. Il est l’un des trois enfants de Loki et combat Thor lors du Ragnarök."),
        Question(20132, "Quel dieu égyptien est associé au soleil ?", listOf("Râ", "Osiris", "Anubis", "Seth"), 0, "Mythologie", Difficulty.EASY, explanation = "Râ est le dieu solaire majeur de la mythologie égyptienne, souvent représenté avec une tête de faucon surmontée d'un disque solaire."),
        Question(20133, "Qui est l'épouse de Zeus dans la mythologie grecque ?", listOf("Héra", "Athéna", "Aphrodite", "Déméter"), 0, "Mythologie", Difficulty.EASY, explanation = "Héra est la déesse du mariage et de la famille, sœur et épouse légitime de Zeus, roi des dieux de l'Olympe."),
        Question(20134, "Quelle nymphe s'est transformée en laurier pour échapper à Apollon ?", listOf("Daphné", "Écho", "Syrinx", "Calypso"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, Daphné est une nymphe poursuivie par Apollon, qui la transforme en laurier pour lui échapper, faisant de cet arbre un symbole sacré pour le dieu."),
        Question(20135, "Quel roi a eu le pouvoir de transformer tout en or ?", listOf("Midas", "Crésus", "Priam", "Agamemnon"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, le roi Midas reçut de Dionysos le pouvoir de transformer en or tout ce qu'il touchait, un don qui devint une malédiction lorsqu'il ne put plus manger ni boire."),
        Question(20136, "Dans la mythologie celtique, qu'est-ce que l'Avalon ?", listOf("L'île des pommes / paradis", "Le monde souterrain", "La forêt sacrée", "Le lac enchanté"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie celtique, Avalon est une île légendaire associée aux pommes, symbole d'immortalité, et considérée comme un paradis ou un royaume des dieux."),
        Question(20137, "Quel héros grec est invulnérable sauf au talon ?", listOf("Achille", "Héraclès", "Persée", "Ajax"), 0, "Mythologie", Difficulty.EASY, explanation = "Selon la mythologie grecque, sa mère Thétis le plongea dans le Styx pour le rendre invulnérable, mais le talon par lequel elle le tenait resta vulnérable."),
        Question(20138, "Qui est le dieu nordique de la ruse et du chaos ?", listOf("Loki", "Thor", "Odin", "Tyr"), 0, "Mythologie", Difficulty.EASY, explanation = "Loki est une figure majeure de la mythologie nordique, connu pour ses farces, ses tromperies et son rôle perturbateur parmi les dieux d'Asgard."),
        Question(20139, "Quel oiseau mythique indien est le véhicule de Vishnou ?", listOf("Garuda", "Hamsa", "Jatayu", "Sampati"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie hindoue, Garuda est un immense oiseau divin, souvent représenté avec un corps d'homme et des ailes d'aigle, qui sert de monture (vahana) au dieu Vishnou."),
        Question(20140, "Combien de Muses existait-il dans la mythologie grecque ?", listOf("9", "7", "12", "3"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, les neuf Muses sont les filles de Zeus et de Mnémosyne, chacune présidant à un art ou une science (comme l'épopée, l'histoire ou la danse)."),
        Question(20141, "Quel est le dieu grec du vin ?", listOf("Dionysos", "Apollon", "Pan", "Hermès"), 0, "Mythologie", Difficulty.EASY, explanation = "Dionysos est le dieu grec du vin, de la vigne et de l'ivresse, souvent associé aux fêtes et au théâtre."),
        Question(20142, "Comment se nomme la Valkyrie principale de la mythologie nordique ?", listOf("Brynhildr", "Freyja", "Sif", "Idunn"), 0, "Mythologie", Difficulty.HARD, explanation = "Brynhildr est la plus célèbre des Valkyries, apparaissant dans la légende des Nibelungen et la saga de Sigurd, où elle est punie pour désobéissance en étant plongée dans un sommeil magique."),
        Question(20143, "Quel monstre vivait au fond du lac de Lerne ?", listOf("L'Hydre", "Le Léviathan", "Scylla", "Charybde"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, l'Hydre de Lerne était un serpent d'eau à plusieurs têtes vivant dans le lac de Lerne. Elle fut tuée par Héraclès lors de son deuxième travail."),
        Question(20144, "Quel dieu mésopotamien est le héros de la première épopée connue ?", listOf("Gilgamesh", "Enkidu", "Marduk", "Enlil"), 0, "Mythologie", Difficulty.HARD, explanation = "L'Épopée de Gilgamesh, écrite en cunéiforme sur des tablettes d'argile, est considérée comme la plus ancienne œuvre littéraire majeure connue, et elle raconte les aventures du roi légendaire Gilgamesh d'Uruk."),
        Question(20145, "Quelle est la boisson des dieux grecs ?", listOf("Le nectar", "L'ambroisie", "L'hydromel", "Le vin"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, le nectar est la boisson divine qui confère l'immortalité aux dieux de l'Olympe, souvent accompagnée de l'ambroisie, leur nourriture."),
        Question(20146, "Quel dieu aztèque est le serpent à plumes ?", listOf("Quetzalcoatl", "Huitzilopochtli", "Tezcatlipoca", "Tlaloc"), 0, "Mythologie", Difficulty.HARD, explanation = "Quetzalcoatl est l'une des divinités majeures des panthéons mésoaméricains, associé au vent, à la connaissance et à la création, et son nom signifie littéralement serpent à plumes en nahuatl."),
        Question(20147, "Qui a tué le dragon Fáfnir dans la mythologie nordique ?", listOf("Sigurd (Siegfried)", "Thor", "Beowulf", "Ragnar"), 0, "Mythologie", Difficulty.HARD, explanation = "Sigurd, héros de la mythologie nordique, tua le dragon Fáfnir en creusant une fosse et en le frappant au cœur, après avoir été conseillé par Odin."),
        Question(20148, "Quel animal accompagne souvent Athéna ?", listOf("La chouette", "L'aigle", "Le serpent", "Le lion"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, la chouette est l'attribut d'Athéna, déesse de la sagesse, symbolisant la connaissance et la clairvoyance."),
        Question(20149, "Qu'est-ce que l'Olympe dans la mythologie grecque ?", listOf("La montagne des dieux", "Le monde souterrain", "L'île des bienheureux", "La mer"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la mythologie grecque, l'Olympe est le plus haut sommet de Grèce, considéré comme la demeure des douze dieux principaux, où ils vivent sous la direction de Zeus."),
        Question(20150, "Quel fils de Poséidon était un cyclope ?", listOf("Polyphème", "Arion", "Triton", "Orion"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, Polyphème est le plus célèbre des cyclopes, fils de Poséidon et de la nymphe Thoosa. Il apparaît notamment dans l'Odyssée d'Homère, où il est aveuglé par Ulysse.")
    )

    // ===== NATURE — 40 questions =====
    private fun nature(): List<Question> = listOf(
        Question(20202, "Combien de pattes a une araignée ?", listOf("8", "6", "10", "12"), 0, "Nature", Difficulty.EASY, explanation = "Les araignées appartiennent à la classe des arachnides, qui se distinguent des insectes par leurs huit pattes, contre six pour ces derniers."),
        Question(20203, "Quel est le plus grand mammifère marin ?", listOf("La baleine bleue", "Le cachalot", "L'orque", "Le requin-baleine"), 0, "Nature", Difficulty.EASY, explanation = "La baleine bleue est le plus grand mammifère marin, pouvant atteindre 30 mètres de long et peser jusqu'à 200 tonnes, dépassant ainsi tous les autres animaux marins en taille."),
        Question(20204, "Combien de temps vit en moyenne une tortue géante des Galápagos ?", listOf("Plus de 100 ans", "50 ans", "30 ans", "200 ans"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les tortues géantes des Galápagos sont parmi les animaux les plus longévifs, avec une espérance de vie dépassant souvent 100 ans, et certains spécimens atteignent 150 ans. Leur métabolisme lent et leur habitat protégé contribuent à cette longévité exceptionnelle."),
        Question(20205, "Quel arbre peut vivre le plus longtemps ?", listOf("Le pin Bristlecone (5000 ans)", "Le séquoia (3000 ans)", "Le chêne (1000 ans)", "Le baobab (2000 ans)"), 0, "Nature", Difficulty.HARD, explanation = "Le pin Bristlecone, notamment le Pinus longaeva, est l’arbre non clonal le plus vieux au monde, certains spécimens dépassant 4 800 ans, grâce à sa croissance lente et à son adaptation aux conditions extrêmes."),
        Question(20206, "Quel est le plus petit oiseau du monde ?", listOf("Le colibri-abeille", "Le roitelet", "Le mésange bleue", "Le troglodyte"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le colibri-abeille, endémique de Cuba, mesure environ 5 à 6 centimètres de long et pèse moins de 2 grammes, ce qui en fait le plus petit oiseau du monde."),
        Question(20207, "Combien d'yeux a une abeille ?", listOf("5", "2", "4", "8"), 0, "Nature", Difficulty.HARD, explanation = "Les abeilles possèdent deux grands yeux composés et trois petits yeux simples (ocelles) sur le sommet de la tête, ce qui leur donne un total de cinq yeux."),
        Question(20208, "Quel champignon est le plus mortel en France ?", listOf("L'amanite phalloïde", "L'amanite tue-mouches", "Le bolet satan", "La gyromitre"), 0, "Nature", Difficulty.HARD, explanation = "L'amanite phalloïde est responsable de la majorité des intoxications mortelles par champignons en France. Son poison, l'amanitine, détruit le foie et les reins de manière irréversible."),
        Question(20210, "Combien de litres d'eau un éléphant peut-il boire par jour ?", listOf("200 litres", "50 litres", "100 litres", "500 litres"), 0, "Nature", Difficulty.MEDIUM, explanation = "Un éléphant adulte peut boire jusqu'à 200 litres d'eau par jour pour s'hydrater et réguler sa température corporelle, notamment dans les savanes africaines où les ressources en eau sont parfois rares."),
        Question(20211, "Quelle fleur s'ouvre la nuit et se referme le jour ?", listOf("La belle-de-nuit", "Le tournesol", "La rose", "Le lys"), 0, "Nature", Difficulty.MEDIUM, explanation = "La belle-de-nuit, ou Mirabilis jalapa, doit son nom à ses fleurs qui s’épanouissent en fin d’après-midi et restent ouvertes toute la nuit."),
        Question(20212, "Quel insecte produit de la soie ?", listOf("Le ver à soie (Bombyx)", "L'araignée", "La cochenille", "Le papillon"), 0, "Nature", Difficulty.EASY, explanation = "Le ver à soie, ou Bombyx mori, est la chenille d’un papillon domestiqué spécifiquement pour la production de soie. Il file un cocon de fil de soie pour se nymphoser, fil que l’on récolte et dévide pour fabriquer le textile."),
        Question(20213, "Quel est le poisson le plus rapide de l'océan ?", listOf("Le voilier (110 km/h)", "Le thon (80 km/h)", "L'espadon (90 km/h)", "Le barracuda (60 km/h)"), 0, "Nature", Difficulty.HARD, explanation = "Le voilier peut atteindre 110 km/h grâce à sa grande nageoire dorsale qui se replie pour réduire la traînée et à son corps fuselé."),
        Question(20214, "Combien de pattes a un mille-pattes en réalité ?", listOf("Entre 30 et 354", "Exactement 1000", "Entre 500 et 750", "Moins de 20"), 0, "Nature", Difficulty.HARD, explanation = "Le nom \"mille-pattes\" est trompeur : aucune espèce n'atteint ce nombre. Le record se situe entre 30 et 354 pattes selon l'espèce, car leur nombre varie avec l'âge et la segmentation du corps."),
        Question(20215, "Quel animal peut dormir debout ?", listOf("Le cheval", "Le chat", "Le chien", "Le lapin"), 0, "Nature", Difficulty.EASY, explanation = "Les chevaux possèdent un système de verrouillage dans leurs pattes appelé \"appareil de soutien\", leur permettant de dormir debout sans s'effondrer. Cela leur offre une meilleure vigilance face aux prédateurs."),
        Question(20216, "Quel est le plus grand organe d'un arbre ?", listOf("Les racines", "Le tronc", "Les feuilles", "L'écorce"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les racines d'un arbre constituent son plus grand organe car elles s'étendent souvent bien au-delà du houppier, formant un réseau souterrain parfois plus volumineux que la partie visible."),
        Question(20217, "Quel animal a les empreintes digitales similaires à celles de l'homme ?", listOf("Le koala", "Le singe", "Le raton laveur", "Le panda"), 0, "Nature", Difficulty.HARD, explanation = "Les koalas possèdent des crêtes papillaires sur leurs doigts, formant des motifs uniques et complexes, très semblables aux empreintes digitales humaines."),
        Question(20218, "Combien de cœurs a une pieuvre ?", listOf("3", "1", "2", "5"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les pieuvres ont trois cœurs : deux branchiaux qui pompent le sang vers les branchies et un systémique qui l'envoie vers le reste du corps."),
        Question(20219, "Quel est le seul continent sans désert ?", listOf("L'Europe", "L'Amérique du Sud", "L'Asie", "L'Océanie"), 0, "Nature", Difficulty.MEDIUM, explanation = "L'Europe est le seul continent dépourvu de désert aride, car son climat tempéré et ses précipitations régulières empêchent la formation de vastes zones de sable ou de roches sèches."),
        Question(20220, "Quel est le plus petit mammifère du monde ?", listOf("La musaraigne étrusque", "Le colibri", "La chauve-souris bourdon", "La souris pygmée"), 0, "Nature", Difficulty.HARD, explanation = "La musaraigne étrusque pèse en moyenne 1,8 gramme et mesure environ 3,5 centimètres de long, ce qui en fait le plus petit mammifère connu par sa masse corporelle."),
        Question(20221, "Combien de temps un caméléon met-il pour changer de couleur ?", listOf("20 secondes environ", "1 seconde", "5 minutes", "1 heure"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le changement de couleur chez le caméléon est un processus physiologique lent, contrôlé par des cellules cutanées appelées chromatophores, qui nécessite environ 20 secondes pour se réaliser complètement."),
        Question(20222, "Quel gaz produit l'effet de serre le plus puissant ?", listOf("Le méthane", "Le CO2", "L'ozone", "La vapeur d'eau"), 0, "Nature", Difficulty.HARD, explanation = "Le méthane a un potentiel de réchauffement global environ 28 fois supérieur à celui du CO₂ sur 100 ans, ce qui en fait le gaz à effet de serre le plus puissant, bien qu'il soit moins abondant."),
        Question(20224, "Combien de cerveaux a un poulpe ?", listOf("9", "1", "3", "5"), 0, "Nature", Difficulty.HARD, explanation = "Le poulpe possède un cerveau principal et huit ganglions nerveux situés dans chacun de ses bras, ce qui lui confère une intelligence répartie et une grande autonomie des tentacules."),
        Question(20225, "Quel est le plus long fleuve d'Afrique ?", listOf("Le Nil", "Le Congo", "Le Niger", "Le Zambèze"), 0, "Nature", Difficulty.EASY, explanation = "Le Nil s'étend sur environ 6 650 kilomètres, traversant onze pays d'Afrique de l'Est et du Nord-Est, ce qui en fait le plus long fleuve du continent africain."),
        Question(20226, "Quel animal est le symbole du WWF ?", listOf("Le panda géant", "L'ours polaire", "Le tigre", "La baleine"), 0, "Nature", Difficulty.EASY, explanation = "Le panda géant est l'emblème du WWF depuis sa création en 1961, car cet animal menacé d'extinction symbolise parfaitement la mission de l'organisation pour la protection de la faune sauvage."),
        Question(20227, "Quelle est la plus grande forêt tropicale du monde ?", listOf("L'Amazonie", "Le bassin du Congo", "Bornéo", "La forêt de Daintree"), 0, "Nature", Difficulty.EASY, explanation = "L'Amazonie s'étend sur environ 5,5 millions de km², traversant neuf pays d'Amérique du Sud, ce qui en fait la plus vaste forêt tropicale de la planète."),
        Question(20228, "Quel animal migre la plus longue distance ?", listOf("La sterne arctique", "La baleine grise", "Le papillon monarque", "Le caribou"), 0, "Nature", Difficulty.HARD, explanation = "La sterne arctique effectue une migration annuelle de l'Arctique à l'Antarctique, parcourant environ 70 000 kilomètres, soit la plus longue distance de tous les animaux."),
        Question(20229, "Quel est le seul mammifère capable de voler véritablement ?", listOf("La chauve-souris", "L'écureuil volant", "Le colugo", "Le sucre glider"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les chauves-souris sont les seuls mammifères capables de vol actif grâce à leurs ailes formées d'une membrane cutanée, contrairement aux autres mammifères volants comme les écureuils qui ne font que planer."),
        Question(20230, "Combien de dents un requin peut-il avoir au cours de sa vie ?", listOf("Plus de 30 000", "Environ 500", "Environ 5 000", "Environ 100"), 0, "Nature", Difficulty.HARD, explanation = "Les requins perdent et remplacent continuellement leurs dents tout au long de leur vie, certaines espèces pouvant renouveler jusqu'à 30 000 dents en cumulé."),
        Question(20231, "Quelle plante carnivore est la plus connue ?", listOf("La dionée attrape-mouches", "Le népenthès", "La sarracénie", "La drosera"), 0, "Nature", Difficulty.EASY, explanation = "La dionée attrape-mouches est la plus célèbre des plantes carnivores en raison de son mécanisme spectaculaire de piège à mâchoires, qui se referme en une fraction de seconde sur ses proies."),
        Question(20232, "Quel est le volcan le plus actif du monde ?", listOf("Le Kilauea (Hawaï)", "L'Etna (Italie)", "Le Stromboli (Italie)", "Le Piton de la Fournaise"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le Kilauea est considéré comme le volcan le plus actif du monde en raison de ses éruptions quasi continues depuis 1983, avec des coulées de lave fréquentes qui modifient régulièrement le paysage de l'île d'Hawaï."),
        Question(20233, "Quel animal produit la substance la plus venimeuse ?", listOf("La méduse-boîte", "Le serpent Taïpan", "La grenouille poison", "Le scorpion"), 0, "Nature", Difficulty.HARD, explanation = "Le venin de la méduse-boîte, présent dans ses tentacules, est considéré comme le plus mortel au monde, pouvant tuer un humain en quelques minutes."),
        Question(20234, "Combien pèse approximativement un cerveau humain adulte ?", listOf("1,4 kg", "0,5 kg", "2,5 kg", "3 kg"), 0, "Nature", Difficulty.MEDIUM, explanation = "Le cerveau humain adulte pèse en moyenne entre 1,3 et 1,4 kg, soit environ 2% du poids total du corps. Ce poids varie légèrement selon le sexe et la taille de l'individu."),
        Question(20235, "Quel est l'écosystème le plus productif de la planète ?", listOf("Les récifs coralliens", "Les forêts tropicales", "Les prairies", "Les océans profonds"), 0, "Nature", Difficulty.HARD, explanation = "Les récifs coralliens abritent une biodiversité extrêmement dense et des taux de photosynthèse élevés, ce qui en fait les écosystèmes les plus productifs par mètre carré, surpassant même les forêts tropicales."),
        Question(20236, "Quel animal utilise des outils dans la nature ?", listOf("Le corbeau", "Le lion", "L'éléphant", "Le dauphin"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les corbeaux, notamment les corbeaux de Nouvelle-Calédonie, sont célèbres pour fabriquer et utiliser des brindilles afin d’extraire des insectes de troncs d’arbres."),
        Question(20237, "Combien d'espèces de fourmis existent environ ?", listOf("Plus de 22 000", "Environ 1 000", "Environ 5 000", "Plus de 100 000"), 0, "Nature", Difficulty.HARD, explanation = "Le nombre exact d'espèces de fourmis est difficile à établir, mais les estimations actuelles dépassent les 22 000 espèces décrites, avec potentiellement autant d'espèces non encore découvertes."),
        Question(20238, "Quel phénomène naturel cause les aurores boréales ?", listOf("Le vent solaire frappant la magnétosphère", "La réflexion de la lumière lunaire", "Les éruptions volcaniques", "Les courants marins"), 0, "Nature", Difficulty.MEDIUM, explanation = "Les aurores boréales se produisent lorsque des particules chargées du vent solaire sont guidées par le champ magnétique terrestre vers les pôles, où elles entrent en collision avec les gaz de l'atmosphère, produisant des lumières colorées."),
        Question(20239, "Quel est le félin le plus menacé au monde ?", listOf("Le lynx ibérique", "Le tigre de Sumatra", "Le léopard des neiges", "Le guépard asiatique"), 0, "Nature", Difficulty.HARD, explanation = "Le lynx ibérique est considéré comme le félin le plus menacé au monde en raison de la destruction de son habitat et du déclin de sa principale proie, le lapin de garenne, avec moins de 200 individus adultes dans la nature au début des années 2000."),
        Question(20240, "Quel est le plus vieil organisme vivant connu ?", listOf("Un champignon (Armillaria) de 2400 ans", "Un séquoia de 3000 ans", "Une méduse immortelle", "Un pin Bristlecone de 5000 ans"), 0, "Nature", Difficulty.EXPERT, explanation = "L'Armillaria ostoyae, un champignon parasite des racines d'arbres, forme un réseau souterrain continu dans l'Oregon, estimé à 2400 ans, ce qui en fait l'organisme vivant le plus ancien connu.")
    )

    // ===== POLITIQUE — 40 questions =====
    private fun politique(): List<Question> = listOf(
        Question(20301, "Combien de pays composent l'Union européenne (2024) ?", listOf("27", "28", "25", "30"), 0, "Politique", Difficulty.MEDIUM, explanation = "L'Union européenne compte 27 États membres depuis le retrait du Royaume-Uni en 2020. Ce nombre est stable en 2024, sans nouvel élargissement ou départ récent."),
        Question(20302, "Quel est le siège du Parlement européen ?", listOf("Strasbourg", "Bruxelles", "Luxembourg", "La Haye"), 0, "Politique", Difficulty.MEDIUM, explanation = "Strasbourg est le siège officiel du Parlement européen, où se tiennent les sessions plénières, tandis que les commissions se réunissent à Bruxelles."),
        Question(20303, "Combien de membres permanents siègent au Conseil de sécurité de l'ONU ?", listOf("5", "10", "7", "15"), 0, "Politique", Difficulty.MEDIUM, explanation = "Le Conseil de sécurité de l'ONU compte cinq membres permanents : les États-Unis, la Russie, la Chine, le Royaume-Uni et la France, chacun disposant d'un droit de veto."),
        Question(20304, "Quel pays a le plus vieux parlement du monde encore en activité ?", listOf("L'Islande (Althing)", "Le Royaume-Uni", "La Grèce", "La Suisse"), 0, "Politique", Difficulty.HARD, explanation = "L'Althing islandais a été fondé en 930 après J.-C., ce qui en fait la plus ancienne assemblée parlementaire encore en activité."),
        Question(20305, "Qui a été le premier secrétaire général de l'ONU ?", listOf("Trygve Lie", "Dag Hammarskjöld", "U Thant", "Kurt Waldheim"), 0, "Politique", Difficulty.HARD, explanation = "Trygve Lie, un diplomate norvégien, a été le premier à occuper ce poste de 1946 à 1952, après la création de l'ONU en 1945."),
        Question(20307, "Quel président américain a démissionné suite au Watergate ?", listOf("Richard Nixon", "Gerald Ford", "Lyndon Johnson", "Jimmy Carter"), 0, "Politique", Difficulty.MEDIUM, explanation = "Richard Nixon a démissionné en 1974 pour éviter une procédure de destitution après le scandale du Watergate, où son administration avait espionné le siège du Parti démocrate."),
        Question(20308, "Combien d'amendements contient la Constitution américaine ?", listOf("27", "10", "25", "33"), 0, "Politique", Difficulty.HARD, explanation = "La Constitution américaine a été amendée 27 fois depuis son adoption en 1787, les dix premiers amendements formant la Déclaration des droits."),
        Question(20309, "Quel est le système politique du Royaume-Uni ?", listOf("Monarchie constitutionnelle parlementaire", "République fédérale", "Monarchie absolue", "République présidentielle"), 0, "Politique", Difficulty.EASY, explanation = "Le Royaume-Uni est une monarchie constitutionnelle où le roi ou la reine est le chef d'État, mais le pouvoir est exercé par un parlement élu, ce qui en fait une démocratie parlementaire."),
        Question(20310, "Qui a été la première femme Premier ministre au monde ?", listOf("Sirimavo Bandaranaike (Sri Lanka)", "Margaret Thatcher", "Golda Meir", "Indira Gandhi"), 0, "Politique", Difficulty.HARD, explanation = "Sirimavo Bandaranaike est devenue Première ministre de Sri Lanka en 1960, après l'assassinat de son mari, ce qui en fait la première femme à occuper ce poste dans le monde."),
        Question(20311, "Combien de républiques la France a-t-elle connues ?", listOf("5", "4", "3", "6"), 0, "Politique", Difficulty.MEDIUM, explanation = "Depuis la Révolution française, la France a connu cinq régimes républicains, la Cinquième République étant celle établie en 1958 et toujours en vigueur."),
        Question(20312, "Quel traité a fondé la Communauté économique européenne ?", listOf("Le traité de Rome (1957)", "Le traité de Maastricht", "Le traité de Lisbonne", "Le traité de Paris"), 0, "Politique", Difficulty.HARD, explanation = "Le traité de Rome, signé en 1957 par six pays, a institué la Communauté économique européenne (CEE) en créant un marché commun et des politiques économiques communes."),
        Question(20313, "Quel pays pratique la démocratie directe avec des référendums fréquents ?", listOf("La Suisse", "La Suède", "Les Pays-Bas", "Le Danemark"), 0, "Politique", Difficulty.MEDIUM, explanation = "La Suisse est un cas unique au monde où les citoyens peuvent voter plusieurs fois par an sur des lois et des modifications constitutionnelles via des référendums et des initiatives populaires, ce qui en fait un exemple de démocratie directe."),
        Question(20314, "Qui est le fondateur de la Croix-Rouge ?", listOf("Henry Dunant", "Florence Nightingale", "Albert Schweitzer", "Fridtjof Nansen"), 0, "Politique", Difficulty.MEDIUM, explanation = "Henry Dunant, homme d'affaires suisse, a fondé la Croix-Rouge en 1863 après avoir été marqué par les souffrances des soldats blessés lors de la bataille de Solférino en 1859."),
        Question(20315, "Quel organe de l'ONU peut imposer des sanctions internationales ?", listOf("Le Conseil de sécurité", "L'Assemblée générale", "La Cour internationale de Justice", "Le Secrétariat"), 0, "Politique", Difficulty.MEDIUM, explanation = "Le Conseil de sécurité de l'ONU est le seul organe habilité à adopter des résolutions contraignantes, y compris des sanctions économiques ou militaires, pour maintenir la paix et la sécurité internationales."),
        Question(20316, "Quel leader a mené la lutte anti-apartheid en Afrique du Sud ?", listOf("Nelson Mandela", "Desmond Tutu", "Steve Biko", "Thabo Mbeki"), 0, "Politique", Difficulty.EASY, explanation = "Nelson Mandela a été une figure centrale de l'opposition au régime d'apartheid en Afrique du Sud, dirigeant le Congrès national africain (ANC) et passant 27 ans en prison avant de devenir le premier président noir du pays en 1994."),
        Question(20318, "En quelle année l'ONU a-t-elle été fondée ?", listOf("1945", "1948", "1942", "1950"), 0, "Politique", Difficulty.MEDIUM, explanation = "L'ONU a été créée le 24 octobre 1945, après la Seconde Guerre mondiale, pour remplacer la Société des Nations et promouvoir la paix et la coopération internationale."),
        Question(20319, "Quel pays a le droit de veto au Conseil de sécurité de l'ONU parmi ceux-ci ?", listOf("La France", "L'Allemagne", "Le Japon", "Le Brésil"), 0, "Politique", Difficulty.MEDIUM, explanation = "La France est l’un des cinq membres permanents du Conseil de sécurité de l’ONU, avec les États-Unis, le Royaume-Uni, la Russie et la Chine, ce qui lui confère un droit de veto."),
        Question(20320, "Qu'est-ce que la séparation des pouvoirs selon Montesquieu ?", listOf("Exécutif, législatif, judiciaire", "Militaire, civil, religieux", "Fédéral, régional, local", "Royal, aristocratique, populaire"), 0, "Politique", Difficulty.MEDIUM, explanation = "Montesquieu distingue trois fonctions dans l'État pour éviter les abus de pouvoir : exécuter les lois, les voter et juger leurs infractions. Ce modèle inspire la plupart des démocraties modernes."),
        Question(20321, "Quel président français a instauré la Ve République ?", listOf("Charles de Gaulle", "François Mitterrand", "Georges Pompidou", "René Coty"), 0, "Politique", Difficulty.EASY, explanation = "Charles de Gaulle a instauré la Ve République en 1958, en rédigeant une nouvelle Constitution pour remplacer la IVe République, affaiblie par l'instabilité politique et la guerre d'Algérie."),
        Question(20322, "Combien de sénateurs siègent au Sénat américain ?", listOf("100", "50", "435", "150"), 0, "Politique", Difficulty.MEDIUM, explanation = "Le Sénat américain compte 100 membres, car chaque État, quelle que soit sa population, élit deux sénateurs. Les États-Unis comprennent 50 États, ce qui donne 50 × 2 = 100 sénateurs."),
        Question(20323, "Quel mouvement politique est né de la Révolution française ?", listOf("Gauche et Droite (placement dans l'assemblée)", "Le communisme", "Le fascisme", "L'anarchisme"), 0, "Politique", Difficulty.HARD, explanation = "Lors de la Révolution française, les députés siégeant à gauche du président de l'Assemblée nationale étaient favorables aux réformes radicales, tandis que ceux à droite défendaient l'ordre établi, donnant naissance aux concepts politiques de gauche et de droite."),
        Question(20324, "Quel pays est le plus peuplé du monde ?", listOf("L'Inde", "La Chine", "Les États-Unis", "L'Indonésie"), 0, "Politique", Difficulty.EASY, explanation = "L'Inde a dépassé la Chine en 2023 pour devenir le pays le plus peuplé du monde, avec environ 1,4 milliard d'habitants."),
        Question(20325, "Quel est l'âge minimum pour être président aux États-Unis ?", listOf("35 ans", "30 ans", "40 ans", "25 ans"), 0, "Politique", Difficulty.MEDIUM, explanation = "La Constitution américaine fixe à 35 ans l'âge minimum pour être président, une condition établie pour garantir une maturité et une expérience suffisantes."),
        Question(20326, "Qu'est-ce que le G7 ?", listOf("Un forum de 7 pays industrialisés", "Un traité commercial", "Une alliance militaire", "Un organisme de l'ONU"), 0, "Politique", Difficulty.EASY, explanation = "Le G7 est un groupe informel réunissant les sept plus grandes économies avancées du monde (États-Unis, Japon, Allemagne, France, Royaume-Uni, Italie et Canada) pour discuter de questions économiques et politiques internationales."),
        Question(20327, "Quel est le nom du parlement allemand ?", listOf("Le Bundestag", "Le Reichstag", "Le Bundesrat", "Le Landtag"), 0, "Politique", Difficulty.MEDIUM, explanation = "Le Bundestag est l'assemblée parlementaire fédérale allemande, élue au suffrage universel direct, et constitue la chambre basse du système bicaméral allemand."),
        Question(20328, "En quelle année les femmes ont-elles obtenu le droit de vote en France ?", listOf("1944", "1936", "1918", "1952"), 0, "Politique", Difficulty.MEDIUM, explanation = "Le droit de vote a été accordé aux femmes françaises par l'ordonnance du 21 avril 1944, signée par le général de Gaulle. Elles ont voté pour la première fois lors des élections municipales de 1945."),
        Question(20329, "Quel est le siège de la Cour internationale de Justice ?", listOf("La Haye", "Genève", "New York", "Bruxelles"), 0, "Politique", Difficulty.HARD, explanation = "La Cour internationale de Justice, principal organe judiciaire des Nations Unies, a son siège au Palais de la Paix à La Haye, aux Pays-Bas."),
        Question(20330, "Quel type de régime est une théocratie ?", listOf("Un régime dirigé selon des principes religieux", "Un régime militaire", "Un régime démocratique", "Un régime monarchique"), 0, "Politique", Difficulty.MEDIUM, explanation = "Dans une théocratie, le pouvoir politique est exercé par des autorités religieuses ou au nom d'une divinité, les lois étant fondées sur des textes sacrés."),
        Question(20331, "Qui a prononcé 'I have a dream' ?", listOf("Martin Luther King Jr.", "Malcolm X", "Barack Obama", "John F. Kennedy"), 0, "Politique", Difficulty.EASY, explanation = "Martin Luther King Jr. a prononcé ce discours le 28 août 1963 lors de la marche pour l'emploi et la liberté à Washington, devenant un symbole majeur du mouvement des droits civiques aux États-Unis."),
        Question(20332, "Combien de pays sont membres de l'ONU (2024) ?", listOf("193", "150", "200", "180"), 0, "Politique", Difficulty.MEDIUM, explanation = "L'ONU comptait 193 États membres en 2024, ce qui correspond à la quasi-totalité des nations souveraines reconnues internationalement. Le Soudan du Sud a été le dernier pays admis, en 2011."),
        Question(20333, "Quel est le plus ancien État souverain d'Europe ?", listOf("Saint-Marin", "Le Vatican", "Monaco", "Le Liechtenstein"), 0, "Politique", Difficulty.HARD, explanation = "Saint-Marin a été fondé en 301 après J.-C. et sa constitution date de 1600, ce qui en fait la plus ancienne république et le plus vieil État souverain d'Europe encore existant."),
        Question(20334, "Quel président américain a ordonné le bombardement d'Hiroshima ?", listOf("Harry Truman", "Franklin Roosevelt", "Dwight Eisenhower", "John F. Kennedy"), 0, "Politique", Difficulty.MEDIUM, explanation = "Harry Truman était le président des États-Unis en août 1945, lorsqu'il a autorisé l'utilisation de la bombe atomique sur Hiroshima pour mettre fin à la Seconde Guerre mondiale."),
        Question(20335, "Qu'est-ce que le droit d'habeas corpus ?", listOf("Le droit de ne pas être détenu sans jugement", "Le droit de vote", "Le droit à la propriété", "Le droit de grâce"), 0, "Politique", Difficulty.HARD, explanation = "L'habeas corpus est un principe juridique fondamental du droit anglo-saxon qui protège contre les détentions arbitraires en exigeant qu'un détenu soit présenté rapidement devant un juge."),
        Question(20336, "Quel pays a aboli la peine de mort en premier ?", listOf("Le Venezuela (1863)", "La France (1981)", "Le Royaume-Uni (1965)", "La Suède (1921)"), 0, "Politique", Difficulty.EXPERT, explanation = "Le Venezuela a aboli la peine de mort en 1863 pour tous les crimes, devenant ainsi le premier pays au monde à le faire, bien avant les nations européennes."),
        Question(20337, "Quel est le nom de la chambre basse du parlement français ?", listOf("L'Assemblée nationale", "Le Sénat", "Le Conseil constitutionnel", "Le Conseil d'État"), 0, "Politique", Difficulty.EASY, explanation = "Le Parlement français est bicaméral, et l'Assemblée nationale, élue au suffrage universel direct, constitue la chambre basse, par opposition au Sénat qui est la chambre haute."),
        Question(20338, "Quel accord international vise à limiter le réchauffement climatique ?", listOf("L'Accord de Paris (2015)", "Le Protocole de Kyoto", "Le Sommet de Rio", "L'Accord de Copenhague"), 0, "Politique", Difficulty.MEDIUM, explanation = "Adopté en 2015 lors de la COP21, l'Accord de Paris engage les pays signataires à maintenir l'augmentation de la température mondiale bien en dessous de 2°C par rapport à l'ère préindustrielle."),
        Question(20339, "Quel État est un État-cité ?", listOf("Singapour", "Le Luxembourg", "Andorre", "Malte"), 0, "Politique", Difficulty.MEDIUM, explanation = "Singapour est une cité-État souveraine, ce qui signifie que son territoire se limite à une seule ville et ses banlieues, sans division en régions ou États fédérés."),
        Question(20340, "Quelle est la durée d'un mandat présidentiel en France ?", listOf("5 ans", "4 ans", "6 ans", "7 ans"), 0, "Politique", Difficulty.EASY, explanation = "Le mandat présidentiel est de 5 ans depuis le référendum de 2000, qui a réduit la durée de 7 à 5 ans pour aligner le mandat sur celui des législatives.")
    )

    // ===== LITTÉRATURE — 40 questions =====
    private fun litterature(): List<Question> = listOf(
        Question(20402, "Quel roman commence par 'Longtemps, je me suis couché de bonne heure' ?", listOf("Du côté de chez Swann (Proust)", "L'Étranger (Camus)", "Madame Bovary (Flaubert)", "Le Rouge et le Noir (Stendhal)"), 0, "Littérature", Difficulty.HARD, explanation = "C'est la phrase d'ouverture de *Du côté de chez Swann*, le premier volume de *À la recherche du temps perdu* de Marcel Proust."),
        Question(20404, "Quel auteur français a écrit 'Le Petit Prince' ?", listOf("Antoine de Saint-Exupéry", "Albert Camus", "André Malraux", "Jean-Paul Sartre"), 0, "Littérature", Difficulty.EASY, explanation = "Antoine de Saint-Exupéry, aviateur et écrivain, publie 'Le Petit Prince' en 1943, une œuvre poétique et philosophique devenue un classique mondial de la littérature jeunesse."),
        Question(20405, "Quel poète a écrit 'Les Fleurs du mal' ?", listOf("Charles Baudelaire", "Arthur Rimbaud", "Paul Verlaine", "Victor Hugo"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Charles Baudelaire a publié ce recueil majeur de la poésie française en 1857, ce qui lui a valu un procès pour outrage à la morale publique."),
        Question(20406, "Qui a écrit '1984' ?", listOf("George Orwell", "Aldous Huxley", "Ray Bradbury", "Isaac Asimov"), 0, "Littérature", Difficulty.EASY, explanation = "George Orwell, de son vrai nom Eric Blair, a publié 1984 en 1949, une dystopie dénonçant les régimes totalitaires et la surveillance de masse."),
        Question(20407, "Quel dramaturge a écrit 'Hamlet' ?", listOf("William Shakespeare", "Molière", "Oscar Wilde", "Christopher Marlowe"), 0, "Littérature", Difficulty.EASY, explanation = "William Shakespeare est l'auteur de la tragédie 'Hamlet', écrite entre 1599 et 1601, considérée comme l'une des œuvres les plus influentes de la littérature anglaise."),
        Question(20409, "Quel mouvement littéraire est associé à Zola ?", listOf("Le naturalisme", "Le romantisme", "Le symbolisme", "Le surréalisme"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Émile Zola est le chef de file du naturalisme, un mouvement littéraire qui vise à appliquer la méthode expérimentale des sciences à l'écriture romanesque."),
        Question(20411, "Quel prix littéraire est le plus prestigieux en France ?", listOf("Le prix Goncourt", "Le prix Femina", "Le prix Renaudot", "Le prix Médicis"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Fondé en 1903 par le testament d'Edmond de Goncourt, ce prix récompense chaque année le meilleur roman en prose française et bénéficie d'une immense couverture médiatique, ce qui en fait le plus convoité et le plus vendeur des prix littéraires français."),
        Question(20413, "Quel roman de Camus met en scène Meursault ?", listOf("L'Étranger", "La Peste", "La Chute", "L'Exil et le Royaume"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Meursault est le narrateur et personnage principal de L'Étranger, roman d'Albert Camus publié en 1942, qui illustre la philosophie de l'absurde."),
        Question(20415, "Quel roman dystopique décrit un 'Meilleur des mondes' ?", listOf("Le Meilleur des mondes (Huxley)", "1984 (Orwell)", "Fahrenheit 451 (Bradbury)", "Nous (Zamiatine)"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Le Meilleur des mondes est un roman d'Aldous Huxley publié en 1932, qui dépeint une société futuriste où les humains sont conditionnés dès la naissance pour maintenir une stabilité sociale."),
        Question(20416, "Quel auteur japonais a écrit 'Kafka sur le rivage' ?", listOf("Haruki Murakami", "Yukio Mishima", "Yasunari Kawabata", "Kenji Miyazawa"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Haruki Murakami est l'auteur de ce roman publié en 2002, mêlant réalisme magique et références à la culture pop."),
        Question(20417, "Qui a écrit 'Les Trois Mousquetaires' ?", listOf("Alexandre Dumas", "Victor Hugo", "Jules Verne", "Honoré de Balzac"), 0, "Littérature", Difficulty.EASY, explanation = "Alexandre Dumas a publié ce roman d'aventures historique en feuilleton en 1844, avec la collaboration d'Auguste Maquet."),
        Question(20418, "Quel mouvement littéraire André Breton a-t-il fondé ?", listOf("Le surréalisme", "Le dadaïsme", "L'existentialisme", "Le symbolisme"), 0, "Littérature", Difficulty.HARD, explanation = "André Breton a publié le Manifeste du surréalisme en 1924, définissant ce mouvement qui prône l'expression du fonctionnement réel de la pensée, en l'absence de tout contrôle exercé par la raison."),
        Question(20419, "Combien de livres composent 'À la recherche du temps perdu' de Proust ?", listOf("7", "5", "10", "3"), 0, "Littérature", Difficulty.HARD, explanation = "Originellement conçue comme un cycle de trois romans, l'œuvre de Proust s'est développée en sept tomes publiés entre 1913 et 1927, dont les titres incluent *Du côté de chez Swann* et *Le Temps retrouvé*."),
        Question(20421, "Quel philosophe a écrit 'La Nausée' ?", listOf("Jean-Paul Sartre", "Albert Camus", "Simone de Beauvoir", "Maurice Merleau-Ponty"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Jean-Paul Sartre a publié \"La Nausée\" en 1938, un roman philosophique qui explore l'absurdité de l'existence et le concept de contingence, préfigurant son œuvre existentialiste majeure \"L'Être et le Néant\"."),
        Question(20422, "Quel auteur a inventé le mot 'utopie' ?", listOf("Thomas More", "Francis Bacon", "Platon", "Voltaire"), 0, "Littérature", Difficulty.HARD, explanation = "Thomas More a forgé le terme utopie en 1516 pour le titre de son ouvrage décrivant une société idéale, combinant le grec ou-topos (lieu qui n'existe pas) et eu-topos (lieu heureux)."),
        Question(20423, "Qui a écrit 'Le Seigneur des anneaux' ?", listOf("J.R.R. Tolkien", "C.S. Lewis", "George R.R. Martin", "Terry Pratchett"), 0, "Littérature", Difficulty.EASY, explanation = "J.R.R. Tolkien, philologue et professeur à Oxford, a publié 'Le Seigneur des anneaux' entre 1954 et 1955, créant un univers de fantasy complet avec ses langues et son histoire."),
        Question(20424, "Quel roman de Flaubert a été censuré pour immoralité ?", listOf("Madame Bovary", "L'Éducation sentimentale", "Salammbô", "Bouvard et Pécuchet"), 0, "Littérature", Difficulty.HARD, explanation = "Madame Bovary a été censuré pour immoralité en 1857, car ses descriptions de l'adultère et du suicide étaient jugées contraires aux bonnes mœurs. Flaubert fut acquitté, mais le procès contribua à la célébrité du roman."),
        Question(20425, "Quel poète français a écrit 'Le Bateau ivre' à 16 ans ?", listOf("Arthur Rimbaud", "Paul Verlaine", "Stéphane Mallarmé", "Charles Baudelaire"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Arthur Rimbaud, prodige de la poésie française, a composé 'Le Bateau ivre' en 1871, à l'âge de 16 ans, marquant ainsi son génie précoce et sa rupture avec les formes poétiques traditionnelles."),
        Question(20426, "Qui a écrit 'Fahrenheit 451' ?", listOf("Ray Bradbury", "George Orwell", "Aldous Huxley", "Philip K. Dick"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Ray Bradbury a publié ce roman de science-fiction dystopique en 1953, dénonçant la censure et l'aliénation par les médias de masse."),
        Question(20427, "Quel auteur africain a écrit 'Les Soleils des indépendances' ?", listOf("Ahmadou Kourouma", "Chinua Achebe", "Léopold Sédar Senghor", "Wole Soyinka"), 0, "Littérature", Difficulty.HARD, explanation = "Ahmadou Kourouma, écrivain ivoirien, a publié ce roman en 1968, devenu un classique de la littérature africaine pour sa critique acerbe des régimes postcoloniaux."),
        Question(20428, "Quel personnage de Molière est un avare célèbre ?", listOf("Harpagon", "Tartuffe", "Alceste", "Scapin"), 0, "Littérature", Difficulty.EASY, explanation = "Harpagon est le personnage principal de la pièce *L'Avare* de Molière, dont le nom est devenu synonyme d'avarice dans la culture française."),
        Question(20429, "Quel prix Nobel de littérature Bob Dylan a-t-il reçu ?", listOf("2016", "2010", "2018", "2014"), 0, "Littérature", Difficulty.HARD, explanation = "Bob Dylan a reçu le prix Nobel de littérature en 2016 pour avoir créé de nouvelles expressions poétiques au sein de la grande tradition de la chanson américaine."),
        Question(20431, "Quel genre littéraire est 'Le Roman de Renart' ?", listOf("La fable animalière satirique", "Le roman courtois", "L'épopée", "La chanson de geste"), 0, "Littérature", Difficulty.HARD, explanation = "'Le Roman de Renart' est un ensemble de récits médiévaux mettant en scène des animaux anthropomorphes, notamment le rusé renard Renart, pour critiquer la société et les puissants, ce qui en fait une fable animalière satirique."),
        Question(20432, "Qui a écrit 'Le Comte de Monte-Cristo' ?", listOf("Alexandre Dumas", "Victor Hugo", "Honoré de Balzac", "Théophile Gautier"), 0, "Littérature", Difficulty.EASY, explanation = "Alexandre Dumas a publié ce roman d'aventure en feuilleton entre 1844 et 1846, s'inspirant d'une histoire vraie de vengeance et d'injustice."),
        Question(20433, "Quel auteur est le père de la science-fiction française ?", listOf("Jules Verne", "H.G. Wells", "Isaac Asimov", "Voltaire"), 0, "Littérature", Difficulty.EASY, explanation = "Jules Verne est considéré comme le père de la science-fiction française grâce à ses romans d'anticipation comme \"Voyage au centre de la Terre\" et \"Vingt mille lieues sous les mers\"."),
        Question(20434, "Combien de pièces Shakespeare a-t-il écrites environ ?", listOf("37", "20", "50", "15"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Le canon shakespearien reconnu par les spécialistes comprend 37 pièces, dont 36 publiées dans le Premier Folio de 1623 et une ajoutée ultérieurement, Périclès."),
        Question(20435, "Quel mouvement le poème 'Liberté' de Paul Éluard représente-t-il ?", listOf("La Résistance", "Le surréalisme", "Le dadaïsme", "Le romantisme"), 0, "Littérature", Difficulty.HARD, explanation = "Publié clandestinement en 1942, ce poème fut parachuté par les avions alliés pour soutenir la lutte contre l'occupation nazie, devenant un symbole majeur de la Résistance française."),
        Question(20436, "Qui a écrit 'Le Meilleur des mondes' ?", listOf("Aldous Huxley", "George Orwell", "Philip K. Dick", "Ray Bradbury"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Aldous Huxley a publié ce roman dystopique en 1932, décrivant une société future technocratique et totalitaire."),
        Question(20437, "Quel roman de Mary Shelley est considéré comme le premier roman de SF ?", listOf("Frankenstein", "Dracula", "Le Dernier Homme", "Mathilda"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Frankenstein, publié en 1818, est souvent cité comme le premier roman de science-fiction car il explore la création artificielle de la vie par la science, un thème fondateur du genre."),
        Question(20438, "Quel auteur a créé le commissaire Maigret ?", listOf("Georges Simenon", "Agatha Christie", "Maurice Leblanc", "Gaston Leroux"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Georges Simenon a créé le commissaire Maigret en 1931 avec le roman \"Pietr-le-Letton\". Ce personnage emblématique apparaît dans 75 romans et 28 nouvelles de l'écrivain belge."),
        Question(20439, "Quel roman commence par 'Aujourd'hui, maman est morte' ?", listOf("L'Étranger de Camus", "La Nausée de Sartre", "La Peste de Camus", "Les Mots de Sartre"), 0, "Littérature", Difficulty.HARD, explanation = "Albert Camus ouvre L'Étranger par cette phrase emblématique, marquant le ton détaché et absurde du personnage de Meursault face à la mort de sa mère."),
        Question(20440, "Quelle autrice a écrit 'Le Deuxième Sexe' ?", listOf("Simone de Beauvoir", "Virginia Woolf", "Marguerite Duras", "George Sand"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Simone de Beauvoir a publié \"Le Deuxième Sexe\" en 1949, un essai fondateur du féminisme moderne qui analyse la condition des femmes à travers l'histoire et la société.")
    )

    // ===== ÉCONOMIE — 30 questions =====
    private fun economie(): List<Question> = listOf(
        Question(20502, "Qui est considéré comme le père de l'économie moderne ?", listOf("Adam Smith", "Karl Marx", "John Maynard Keynes", "David Ricardo"), 0, "Économie", Difficulty.MEDIUM, explanation = "Adam Smith a posé les bases de la pensée économique classique avec son ouvrage \"La Richesse des nations\" en 1776, où il a introduit des concepts clés comme la main invisible et la division du travail."),
        Question(20504, "Quelle monnaie est utilisée au Japon ?", listOf("Le yen", "Le won", "Le yuan", "Le ringgit"), 0, "Économie", Difficulty.EASY, explanation = "Le yen est la monnaie officielle du Japon depuis 1871, émise par la Banque du Japon. Son symbole ¥ et son code ISO JPY sont reconnus internationalement."),
        Question(20505, "Qu'est-ce qu'une récession économique ?", listOf("Deux trimestres consécutifs de croissance négative", "Une hausse du chômage", "Une baisse de la bourse", "Une crise bancaire"), 0, "Économie", Difficulty.MEDIUM, explanation = "La définition technique la plus courante d'une récession est une baisse du produit intérieur brut (PIB) pendant au moins deux trimestres consécutifs."),
        Question(20506, "Quelle institution fixe les taux d'intérêt dans la zone euro ?", listOf("La BCE", "La Fed", "Le FMI", "La Banque mondiale"), 0, "Économie", Difficulty.MEDIUM, explanation = "La Banque centrale européenne (BCE) est responsable de la politique monétaire de la zone euro, incluant la fixation des taux d'intérêt directeurs pour contrôler l'inflation et soutenir l'économie."),
        Question(20507, "En quelle année a eu lieu le krach de Wall Street ?", listOf("1929", "1933", "1920", "1937"), 0, "Économie", Difficulty.MEDIUM, explanation = "Le krach boursier de Wall Street a débuté le jeudi 24 octobre 1929, marquant le début de la Grande Dépression, la plus grave crise économique du XXe siècle."),
        Question(20509, "Quel économiste est associé au keynésianisme ?", listOf("John Maynard Keynes", "Milton Friedman", "Friedrich Hayek", "Adam Smith"), 0, "Économie", Difficulty.MEDIUM, explanation = "John Maynard Keynes a fondé cette école de pensée économique dans les années 1930, prônant l'intervention de l'État pour réguler l'économie et lutter contre le chômage."),
        Question(20510, "Quelle est la monnaie du Royaume-Uni ?", listOf("La livre sterling", "L'euro", "Le dollar", "Le franc"), 0, "Économie", Difficulty.EASY, explanation = "La livre sterling, souvent appelée livre, est la monnaie officielle du Royaume-Uni depuis des siècles, utilisée dans ses quatre nations constitutives."),
        Question(20511, "Que signifie le terme 'bulle spéculative' ?", listOf("Une hausse des prix déconnectée de la valeur réelle", "Un investissement très rentable", "Une crise bancaire", "Un effondrement monétaire"), 0, "Économie", Difficulty.MEDIUM, explanation = "Une bulle spéculative se forme quand les prix d'un actif (immobilier, actions) montent bien au-delà de sa valeur fondamentale, portés par un engouement irrationnel et des achats spéculatifs, avant de s'effondrer brutalement."),
        Question(20512, "Quel pays a le PIB le plus élevé au monde ?", listOf("Les États-Unis", "La Chine", "Le Japon", "L'Allemagne"), 0, "Économie", Difficulty.EASY, explanation = "Les États-Unis possèdent la plus grande économie mondiale, avec un PIB dépassant les 25 000 milliards de dollars, grâce à leur domination dans les services, la technologie et la consommation intérieure."),
        Question(20513, "Qu'est-ce que l'offre et la demande ?", listOf("Le mécanisme de fixation des prix sur un marché", "Un contrat commercial", "Un système de distribution", "Un index boursier"), 0, "Économie", Difficulty.EASY, explanation = "En économie, l'offre et la demande sont les forces qui interagissent sur un marché pour déterminer le prix d'équilibre d'un bien ou d'un service."),
        Question(20514, "Quel est le rôle du FMI ?", listOf("Promouvoir la stabilité financière internationale", "Financer les guerres", "Gérer les douanes mondiales", "Fixer les prix du pétrole"), 0, "Économie", Difficulty.MEDIUM, explanation = "Le FMI a été créé en 1944 pour surveiller le système monétaire mondial et éviter les crises financières, en offrant des prêts aux pays en difficulté et en conseillant des politiques économiques."),
        Question(20516, "Quelle est la principale bourse mondiale par capitalisation ?", listOf("Le NYSE (New York Stock Exchange)", "Le NASDAQ", "Le LSE (Londres)", "Le TSE (Tokyo)"), 0, "Économie", Difficulty.MEDIUM, explanation = "Le NYSE est la plus grande bourse du monde en termes de capitalisation boursière totale, dépassant largement le Nasdaq et les bourses asiatiques comme le Tokyo Stock Exchange."),
        Question(20517, "Qu'est-ce que le commerce équitable ?", listOf("Un commerce garantissant un prix juste aux producteurs", "Un commerce sans taxes", "Un échange entre pays riches", "Un système de troc"), 0, "Économie", Difficulty.EASY, explanation = "Le commerce équitable vise à assurer une rémunération décente aux producteurs des pays en développement, souvent marginalisés dans les échanges mondiaux. Ce système fixe un prix minimum garanti pour leurs produits, au-delà des fluctuations du marché classique."),
        Question(20518, "Quel accord a créé la zone de libre-échange nord-américaine ?", listOf("L'ALENA (NAFTA)", "Le TAFTA", "Le MERCOSUR", "L'ASEAN"), 0, "Économie", Difficulty.HARD, explanation = "L'Accord de libre-échange nord-américain (ALENA), signé en 1994 entre les États-Unis, le Canada et le Mexique, a supprimé la plupart des barrières tarifaires entre ces trois pays. Il a été remplacé en 2020 par l'AEUMC (USMCA)."),
        Question(20519, "Qu'est-ce que la dette publique ?", listOf("L'ensemble des emprunts d'un État", "Le budget de l'État", "Les impôts collectés", "Le déficit commercial"), 0, "Économie", Difficulty.EASY, explanation = "La dette publique désigne le total des sommes empruntées par l'État auprès d'investisseurs (banques, particuliers, autres pays) pour financer ses dépenses lorsqu'elles dépassent ses recettes."),
        Question(20520, "Quelle crypto-monnaie a été créée en premier ?", listOf("Bitcoin", "Ethereum", "Litecoin", "Ripple"), 0, "Économie", Difficulty.EASY, explanation = "Bitcoin a été lancé en 2009 par une personne ou un groupe sous le pseudonyme Satoshi Nakamoto, ce qui en fait la première crypto-monnaie décentralisée."),
        Question(20521, "Qui a écrit 'Le Capital' ?", listOf("Karl Marx", "Adam Smith", "Friedrich Engels", "Max Weber"), 0, "Économie", Difficulty.MEDIUM, explanation = "Publié en 1867, cet ouvrage fondateur du marxisme analyse le mode de production capitaliste et ses contradictions, posant les bases de la critique de l'économie politique."),
        Question(20522, "Qu'est-ce que le taux de change ?", listOf("La valeur d'une monnaie par rapport à une autre", "Le taux d'intérêt bancaire", "Le coût de la vie", "L'inflation annuelle"), 0, "Économie", Difficulty.EASY, explanation = "Le taux de change est le prix d'une devise exprimé dans une autre, permettant les échanges internationaux et le calcul des importations/exportations."),
        Question(20523, "Quel pays est le plus grand exportateur mondial ?", listOf("La Chine", "Les États-Unis", "L'Allemagne", "Le Japon"), 0, "Économie", Difficulty.MEDIUM, explanation = "La Chine est le premier exportateur mondial depuis 2009, dépassant l'Allemagne, grâce à son rôle d'usine du monde et à sa production massive de biens manufacturés."),
        Question(20524, "Qu'est-ce qu'un monopole ?", listOf("Un seul vendeur sur un marché", "Plusieurs vendeurs en concurrence", "Un marché avec deux acteurs", "Un cartel de prix"), 0, "Économie", Difficulty.EASY, explanation = "Un monopole désigne une situation où une seule entreprise ou entité contrôle l'offre d'un bien ou service, sans concurrent direct sur le marché."),
        Question(20525, "Quelle crise a secoué le monde en 2008 ?", listOf("La crise des subprimes", "La crise de l'euro", "La crise pétrolière", "La crise asiatique"), 0, "Économie", Difficulty.MEDIUM, explanation = "La crise des subprimes est née de l'effondrement du marché immobilier américain, où des prêts hypothécaires à risque ont été massivement accordés puis revendus sous forme de produits financiers toxiques, provoquant une récession mondiale."),
        Question(20526, "Quel économiste a théorisé la 'main invisible' ?", listOf("Adam Smith", "David Ricardo", "John Stuart Mill", "Thomas Malthus"), 0, "Économie", Difficulty.HARD, explanation = "Adam Smith a introduit ce concept dans son ouvrage *La Richesse des nations* (1776) pour décrire comment les actions individuelles guidées par l'intérêt personnel peuvent indirectement bénéficier à l'ensemble de la société."),
        Question(20527, "Qu'est-ce que le PIB par habitant ?", listOf("Le PIB divisé par le nombre d'habitants", "Le revenu moyen par ménage", "Le salaire minimum national", "La production par entreprise"), 0, "Économie", Difficulty.EASY, explanation = "Le PIB par habitant permet de mesurer le niveau de vie moyen d'un pays en rapportant la production totale de richesses à sa population."),
        Question(20528, "Quel indice boursier français est le plus connu ?", listOf("Le CAC 40", "Le SBF 120", "Le DAX", "Le FTSE"), 0, "Économie", Difficulty.EASY, explanation = "Le CAC 40 est l'indice boursier de référence de la Bourse de Paris, regroupant les 40 plus grandes capitalisations françaises cotées sur Euronext Paris."),
        Question(20530, "Quel concept économique Thomas Piketty a-t-il popularisé ?", listOf("Les inégalités de patrimoine (r>g)", "La courbe de Laffer", "L'avantage comparatif", "La destruction créatrice"), 0, "Économie", Difficulty.EXPERT, explanation = "Dans son ouvrage Le Capital au XXIe siècle, Thomas Piketty a démontré que le taux de rendement du capital (r) tend à être supérieur au taux de croissance économique (g), ce qui accroît mécaniquement les inégalités de patrimoine.")
    )

    // ===== SCIENCES HUMAINES — 25 questions =====
    private fun sciencesHumaines(): List<Question> = listOf(
        Question(20601, "Qui est le père de la psychanalyse ?", listOf("Sigmund Freud", "Carl Jung", "Jacques Lacan", "Alfred Adler"), 0, "Sciences Humaines", Difficulty.EASY, explanation = "Sigmund Freud a développé la psychanalyse à la fin du XIXe siècle, en introduisant des concepts clés comme l'inconscient, la sexualité infantile et l'interprétation des rêves."),
        Question(20602, "Qu'est-ce que la pyramide de Maslow ?", listOf("La hiérarchie des besoins humains", "Une technique de management", "Un modèle économique", "Un type d'architecture"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "La pyramide de Maslow classe les besoins humains par ordre de priorité, des besoins physiologiques de base jusqu'à l'accomplissement de soi, selon le psychologue Abraham Maslow."),
        Question(20603, "Quel sociologue a écrit 'Le Suicide' ?", listOf("Émile Durkheim", "Max Weber", "Pierre Bourdieu", "Marcel Mauss"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Émile Durkheim a publié 'Le Suicide' en 1897, une étude fondatrice qui analyse le taux de suicide comme un fait social lié à l'intégration et à la régulation sociales."),
        Question(20604, "Qu'étudie l'anthropologie ?", listOf("L'humain dans ses dimensions culturelles et biologiques", "Les animaux", "Les minéraux", "Les plantes"), 0, "Sciences Humaines", Difficulty.EASY, explanation = "L'anthropologie se distingue des autres sciences humaines par son approche holistique, combinant l'étude des aspects culturels (comme les langues, les coutumes) et biologiques (comme l'évolution physique) de l'humanité."),
        Question(20605, "Qui a développé la théorie des intelligences multiples ?", listOf("Howard Gardner", "Jean Piaget", "Lev Vygotsky", "B.F. Skinner"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Howard Gardner, psychologue du développement, a proposé cette théorie en 1983 dans son livre Frames of Mind, remettant en cause la vision unique de l'intelligence mesurée par les tests de QI."),
        Question(20606, "Qu'est-ce que le QI ?", listOf("Le quotient intellectuel", "Le questionnaire individuel", "La qualité informatique", "Le quotient d'innovation"), 0, "Sciences Humaines", Difficulty.EASY, explanation = "Le QI, ou quotient intellectuel, est un score issu de tests standardisés conçus pour mesurer certaines capacités cognitives comme le raisonnement logique et la résolution de problèmes."),
        Question(20607, "Quel psychologue est connu pour l'expérience du petit Albert ?", listOf("John Watson", "B.F. Skinner", "Ivan Pavlov", "Carl Rogers"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "John Watson, fondateur du behaviorisme, a mené l'expérience du petit Albert en 1920 pour démontrer le conditionnement classique des peurs chez l'humain."),
        Question(20609, "Qui a théorisé les stades du développement cognitif chez l'enfant ?", listOf("Jean Piaget", "Sigmund Freud", "Erik Erikson", "Lawrence Kohlberg"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "Jean Piaget, psychologue suisse, a élaboré une théorie détaillant quatre stades du développement cognitif de l'enfant, de la naissance à l'adolescence."),
        Question(20610, "Qu'est-ce que l'ethnographie ?", listOf("L'étude descriptive des cultures par immersion", "L'étude des langues anciennes", "L'étude des races", "L'étude de la géographie humaine"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "L'ethnographie repose sur l'observation participante et l'immersion prolongée du chercheur au sein d'une communauté pour décrire ses pratiques culturelles de l'intérieur."),
        Question(20611, "Quel sociologue français a théorisé le 'capital culturel' ?", listOf("Pierre Bourdieu", "Émile Durkheim", "Raymond Aron", "Marcel Mauss"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Pierre Bourdieu a développé ce concept dans les années 1970 pour expliquer comment les connaissances, compétences et dispositions culturelles transmises par la famille et l'école reproduisent les inégalités sociales."),
        Question(20612, "Qu'est-ce que le conditionnement pavlovien ?", listOf("Association d'un stimulus neutre à une réponse réflexe", "Un dressage animal", "Une technique thérapeutique", "Un type de réflexe inné"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "Le physiologiste russe Ivan Pavlov a démontré ce mécanisme en faisant saliver des chiens au son d'une cloche, associé à la présentation de nourriture."),
        Question(20613, "Qui a fondé la linguistique structurale ?", listOf("Ferdinand de Saussure", "Noam Chomsky", "Roman Jakobson", "Claude Lévi-Strauss"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Ferdinand de Saussure est considéré comme le père de la linguistique structurale grâce à son ouvrage posthume \"Cours de linguistique générale\" (1916), qui a révolutionné l'étude du langage en mettant l'accent sur la structure et les relations entre les éléments linguistiques."),
        Question(20614, "Qu'est-ce que la dissonance cognitive ?", listOf("Le malaise causé par des croyances contradictoires", "Un trouble de la mémoire", "Un type de schizophrénie", "Une technique de persuasion"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "Théorisée par Leon Festinger en 1957, la dissonance cognitive décrit l'inconfort mental ressenti lorsqu'une personne tient simultanément deux idées, croyances ou opinions qui entrent en conflit."),
        Question(20615, "Qui a réalisé l'expérience de Milgram sur l'obéissance ?", listOf("Stanley Milgram", "Philip Zimbardo", "Solomon Asch", "Albert Bandura"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Stanley Milgram, psychologue américain, a conçu cette expérience dans les années 1960 pour étudier la soumission à l'autorité, où des participants administraient des chocs électriques fictifs à un acteur."),
        Question(20616, "Qu'est-ce que l'effet Pygmalion ?", listOf("Les attentes influencent positivement la performance", "Un effet de groupe", "Un phénomène de rejet", "Un biais de mémoire"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "Découvert par Robert Rosenthal et Lenore Jacobson, cet effet montre que les attentes élevées d'un enseignant envers ses élèves améliorent leurs résultats scolaires."),
        Question(20617, "Quel courant de pensée B.F. Skinner représente-t-il ?", listOf("Le béhaviorisme", "La psychanalyse", "L'humanisme", "Le cognitivisme"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "B.F. Skinner est le principal représentant du béhaviorisme radical, un courant de la psychologie qui se concentre sur l'étude des comportements observables et rejetant l'introspection."),
        Question(20619, "Qui a développé la théorie de l'attachement ?", listOf("John Bowlby", "Sigmund Freud", "Jean Piaget", "Mary Ainsworth"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "John Bowlby, un psychiatre et psychanalyste britannique, a formulé la théorie de l'attachement dans les années 1950-1960, en étudiant les liens affectifs entre les enfants et leurs figures parentales."),
        Question(20620, "Qu'est-ce que le structuralisme en anthropologie ?", listOf("L'étude des structures universelles de la pensée humaine", "L'étude des bâtiments", "L'analyse des structures sociales", "La classification des langues"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Le structuralisme, développé par Claude Lévi-Strauss, postule que les phénomènes culturels (mythes, parenté) sont organisés par des structures mentales inconscientes et universelles, communes à toute l'humanité."),
        Question(20621, "Quel test psychologique utilise des taches d'encre ?", listOf("Le test de Rorschach", "Le test de QI", "Le MMPI", "Le test TAT"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "Le test de Rorschach, développé par le psychiatre suisse Hermann Rorschach dans les années 1920, utilise des planches de taches d'encre symétriques pour analyser la perception et les traits de personnalité des sujets."),
        Question(20622, "Qui a écrit 'Tristes Tropiques' ?", listOf("Claude Lévi-Strauss", "Marcel Mauss", "Bronisław Malinowski", "Margaret Mead"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Claude Lévi-Strauss, anthropologue français, a publié 'Tristes Tropiques' en 1955, un récit autobiographique mêlant observations ethnographiques de ses voyages au Brésil et réflexions sur la condition humaine."),
        Question(20623, "Qu'est-ce que l'empathie ?", listOf("La capacité à ressentir les émotions d'autrui", "Le désir de dominer", "L'indifférence aux autres", "La peur du jugement"), 0, "Sciences Humaines", Difficulty.EASY, explanation = "L'empathie implique de comprendre et partager les sentiments d'une autre personne, contrairement à la sympathie qui est simplement une réaction de compassion."),
        Question(20624, "Quel est le concept central de la psychologie positive ?", listOf("Le bien-être et l'épanouissement", "Les troubles mentaux", "Les traumatismes", "L'inconscient"), 0, "Sciences Humaines", Difficulty.MEDIUM, explanation = "La psychologie positive, fondée par Martin Seligman, se concentre sur l'étude des forces et des vertus qui permettent aux individus et aux communautés de s'épanouir, plutôt que sur les pathologies."),
        Question(20625, "Qui a créé l'expérience de Stanford sur les prisons ?", listOf("Philip Zimbardo", "Stanley Milgram", "Solomon Asch", "Albert Bandura"), 0, "Sciences Humaines", Difficulty.HARD, explanation = "Philip Zimbardo, psychologue américain, a conçu cette étude en 1971 pour examiner les effets psychologiques du pouvoir et de l'autorité en milieu carcéral simulé.")
    )

    // ===== PHILOSOPHIE — 25 questions =====
    private fun philosophie(): List<Question> = listOf(
        Question(20701, "Quel philosophe a dit 'Je pense, donc je suis' ?", listOf("René Descartes", "Blaise Pascal", "Voltaire", "Jean-Jacques Rousseau"), 0, "Philosophie", Difficulty.EASY, explanation = "Cette phrase est le point de départ de la méthode de René Descartes, qui cherchait une vérité indubitable en doutant de tout. Elle apparaît dans son Discours de la méthode (1637)."),
        Question(20702, "Quel philosophe grec a enseigné dans l'Académie ?", listOf("Platon", "Aristote", "Socrate", "Épicure"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Platon fonda l'Académie à Athènes vers 387 av. J.-C., une école philosophique majeure où il enseigna jusqu'à sa mort."),
        Question(20704, "Quel philosophe a écrit 'Le Prince' ?", listOf("Machiavel", "Hobbes", "Locke", "Rousseau"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Nicolas Machiavel a rédigé \"Le Prince\" en 1513, un traité politique qui analyse les moyens de conquérir et de maintenir le pouvoir, souvent associé à la notion de machiavélisme."),
        Question(20705, "Qui a fondé le stoïcisme ?", listOf("Zénon de Kition", "Épicure", "Diogène", "Aristote"), 0, "Philosophie", Difficulty.HARD, explanation = "Zénon de Kition, un philosophe grec du IVe siècle avant J.-C., a fondé l'école stoïcienne à Athènes vers 300 av. J.-C., en enseignant que la vertu et la raison sont les clés du bonheur."),
        Question(20706, "Quel concept Nietzsche a-t-il développé avec le 'surhomme' ?", listOf("Le dépassement de soi et la création de valeurs", "La supériorité physique", "Le pouvoir politique", "La domination militaire"), 0, "Philosophie", Difficulty.HARD, explanation = "Pour Nietzsche, le surhomme (Übermensch) représente l'individu qui se dépasse sans cesse et crée ses propres valeurs, s'opposant ainsi au conformisme moral et à la passivité du dernier homme."),
        Question(20707, "Qu'est-ce que l'allégorie de la caverne de Platon ?", listOf("Une métaphore sur l'illusion et la connaissance", "Un mythe sur la création du monde", "Une histoire sur la justice", "Un poème sur l'amour"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Dans La République, Platon imagine des prisonniers enchaînés dans une caverne ne voyant que des ombres, symbolisant l'ignorance humaine. La sortie vers la lumière représente l'accès à la connaissance et à la réalité véritable."),
        Question(20708, "Quel philosophe a écrit 'Critique de la raison pure' ?", listOf("Emmanuel Kant", "Georg Hegel", "Arthur Schopenhauer", "Ludwig Wittgenstein"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Emmanuel Kant a publié la *Critique de la raison pure* en 1781, une œuvre fondatrice qui examine les limites et les possibilités de la connaissance humaine sans recourir à l'expérience."),
        Question(20709, "Qu'est-ce que l'utilitarisme ?", listOf("Le plus grand bonheur pour le plus grand nombre", "La recherche du plaisir individuel", "Le respect absolu des règles", "L'obéissance à Dieu"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "L'utilitarisme, fondé par Jeremy Bentham et John Stuart Mill, évalue la moralité d'une action en fonction de sa capacité à maximiser le bien-être général. Le principe du plus grand bonheur pour le plus grand nombre en est le critère central."),
        Question(20710, "Quel philosophe vivait dans un tonneau ?", listOf("Diogène de Sinope", "Socrate", "Platon", "Épicure"), 0, "Philosophie", Difficulty.EASY, explanation = "Diogène de Sinope, figure emblématique de l'école cynique, choisissait de vivre dans un tonneau pour illustrer son mépris des conventions sociales et des besoins matériels."),
        Question(20711, "Qui a développé le concept de 'contrat social' ?", listOf("Jean-Jacques Rousseau", "Thomas Hobbes", "John Locke", "Montesquieu"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Dans son ouvrage majeur *Du contrat social* (1762), Rousseau théorise que la légitimité de l'autorité politique repose sur un pacte entre les citoyens, où chacun aliène ses droits naturels au profit de la volonté générale."),
        Question(20712, "Quel philosophe a été condamné à boire la ciguë ?", listOf("Socrate", "Platon", "Aristote", "Diogène"), 0, "Philosophie", Difficulty.EASY, explanation = "Socrate a été condamné à mort par la cité d'Athènes en 399 av. J.-C. pour impiété et corruption de la jeunesse, et a exécuté sa peine en buvant une coupe de ciguë."),
        Question(20714, "Quel philosophe a écrit 'Être et Temps' ?", listOf("Martin Heidegger", "Jean-Paul Sartre", "Edmund Husserl", "Hannah Arendt"), 0, "Philosophie", Difficulty.HARD, explanation = "Martin Heidegger a publié Être et Temps en 1927, une œuvre majeure de la philosophie existentielle et phénoménologique qui interroge le sens de l'être."),
        Question(20715, "Qu'est-ce que le paradoxe du bateau de Thésée ?", listOf("Un objet reste-t-il le même si toutes ses parties sont remplacées ?", "Peut-on voyager dans le temps ?", "Existe-t-il un dieu ?", "Le monde est-il réel ?"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Ce paradoxe, posé par Plutarque, interroge l'identité d'un objet à travers le temps : si l'on remplace une à une toutes les planches du navire de Thésée, est-ce toujours le même bateau ?"),
        Question(20716, "Quel philosophe a développé la dialectique hégélienne ?", listOf("Georg Wilhelm Friedrich Hegel", "Karl Marx", "Friedrich Engels", "Ludwig Feuerbach"), 0, "Philosophie", Difficulty.HARD, explanation = "Georg Wilhelm Friedrich Hegel a formalisé la dialectique comme un processus triadique (thèse, antithèse, synthèse) dans son œuvre majeure, la Phénoménologie de l'esprit."),
        Question(20718, "Quel philosophe a écrit 'Le mythe de Sisyphe' ?", listOf("Albert Camus", "Jean-Paul Sartre", "Simone de Beauvoir", "Maurice Merleau-Ponty"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Albert Camus a publié *Le Mythe de Sisyphe* en 1942, un essai qui expose sa philosophie de l'absurde, en prenant le mythe de Sisyphe comme métaphore de la condition humaine."),
        Question(20719, "Qu'est-ce que le solipsisme ?", listOf("Seul mon esprit est certain d'exister", "Tout est matière", "Dieu est en tout", "L'univers est infini"), 0, "Philosophie", Difficulty.EXPERT, explanation = "Le solipsisme est une position philosophique radicale qui affirme que la seule certitude est l'existence de son propre esprit, le monde extérieur et les autres consciences n'étant que des constructions possibles."),
        Question(20720, "Quel philosophe a inventé la notion de 'volonté de puissance' ?", listOf("Friedrich Nietzsche", "Arthur Schopenhauer", "Søren Kierkegaard", "Martin Heidegger"), 0, "Philosophie", Difficulty.HARD, explanation = "Friedrich Nietzsche a développé ce concept dans ses œuvres tardives, notamment dans Ainsi parlait Zarathoustra, pour décrire une force fondamentale d'affirmation et de dépassement de soi qui anime tous les êtres vivants."),
        Question(20722, "Quel penseur chinois est le fondateur du taoïsme ?", listOf("Lao Tseu", "Confucius", "Mencius", "Zhuangzi"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Lao Tseu est considéré comme le fondateur du taoïsme, une philosophie chinoise antique centrée sur le concept de Dao (la Voie). Son ouvrage principal, le Tao Te King, pose les bases de cette tradition spirituelle et morale."),
        Question(20723, "Quel concept Simone de Beauvoir a-t-elle développé ?", listOf("On ne naît pas femme, on le devient", "L'existence précède l'essence", "L'homme est un loup pour l'homme", "Je pense donc je suis"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Simone de Beauvoir a développé ce concept dans Le Deuxième Sexe (1949) pour affirmer que la condition féminine est une construction sociale et culturelle, et non une essence biologique."),
        Question(20724, "Qu'est-ce que le matérialisme dialectique ?", listOf("La philosophie de Marx basée sur les contradictions matérielles", "Une religion", "Une théorie physique", "Un mouvement artistique"), 0, "Philosophie", Difficulty.HARD, explanation = "Le matérialisme dialectique, développé par Marx et Engels, combine la dialectique hégélienne (thèse, antithèse, synthèse) à une vision matérialiste de l'histoire, où les contradictions économiques et sociales sont le moteur du changement."),
        Question(20725, "Quel philosophe a écrit 'Éthique à Nicomaque' ?", listOf("Aristote", "Platon", "Socrate", "Épicure"), 0, "Philosophie", Difficulty.HARD, explanation = "Aristote a rédigé l'Éthique à Nicomaque, un ouvrage majeur de philosophie morale dédié à son fils Nicomaque, où il expose sa conception de la vertu et de la vie bonne.")
    )
}
